import{useEffect,useState}from"react";const menu=["Centro de Mando","Cobertura Curricular","Planificaciones IA","Evaluaciones IA","Material de apoyo IA","Mi carpeta","Cursos y Asignaturas","Currículum","Cobertura TP","Alertas y Mejora","Reportes","Administración"];const rows=[["1° Básico A",88,91,82,86],["2° Básico A",84,72,89,80],["4° Básico A",91,78,86,88],["8° Básico A",76,64,81,85],["2° Medio A",89,83,74,90]];function Cell({n}:{n:number}){return <td><span className={n>=80?"good":n>=70?"warn":"bad"}>{n}%</span></td>}function Shell({tab,setTab,children,user,onLogout}:{tab:string,setTab:(x:string)=>void,children:React.ReactNode,user:any,onLogout:()=>void}){const permissions:any={SUPERADMIN:menu,SOSTENEDOR:["Centro de Mando","Cobertura Curricular","Reportes","Administración"],DIRECTOR:["Centro de Mando","Cobertura Curricular","Planificaciones IA","Evaluaciones IA","Material de apoyo IA","Mi carpeta","Cursos y Asignaturas","Currículum","Cobertura TP","Alertas y Mejora","Reportes","Administración"],UTP:["Centro de Mando","Cobertura Curricular","Planificaciones IA","Evaluaciones IA","Mi carpeta","Cursos y Asignaturas","Currículum","Cobertura TP","Alertas y Mejora","Reportes"],DOCENTE:["Planificaciones IA","Evaluaciones IA","Mi carpeta","Cursos y Asignaturas","Currículum","Cobertura TP"]};const visible=user.accountType==="INDIVIDUAL"?["Inicio","Planificaciones IA","Evaluaciones IA","Material de apoyo IA","Mi carpeta","Mi cuenta y suscripción"]:(permissions[user.role]||[]);return <main><aside><div className="brand"><img className="pdLogo" src="/planificaciondocente-logo.png" alt="PlanificaciónDocente"/><div>Planificación<span>Docente</span></div></div><nav>{visible.map((x:string)=><button className={tab===x?"active":""} onClick={()=>setTab(x)} key={x}>{x}</button>)}</nav><div className="role"><b>{user.name}</b><br/><span>{user.accountType==="INDIVIDUAL"?"Docente Individual":roleLabel(user.role)}</span><br/><small>Año académico 2027</small><button className="logout" onClick={onLogout}>Cerrar sesión</button></div></aside><section className="workspace">{children}</section></main>}const Field=({label,children}:{label:string,children:React.ReactNode})=><label><span>{label}</span>{children}</label>;const renderValue=(v:any):string=>{if(v==null)return "";if(typeof v==="string"||typeof v==="number"||typeof v==="boolean")return String(v);if(Array.isArray(v))return v.map(renderValue).filter(Boolean).join(" · ");if(typeof v==="object")return Object.entries(v).map(([k,val])=>{const label=k.replace(/([A-Z])/g," $1").replace(/^./,s=>s.toUpperCase());return label+": "+renderValue(val)}).filter(x=>!x.endsWith(": ")).join(" · ");return String(v)};const roleLabel=(r:string)=>({SUPERADMIN:"Superadministrador",SOSTENEDOR:"Sostenedor",DIRECTOR:"Director",UTP:"Jefe UTP",DOCENTE:"Docente"} as any)[r]||r;const educationStage=(level:string)=>level.includes("Medio")?"Enseñanza Media":level.includes("Básico")?"Enseñanza Básica":"Educación Parvularia";
function Login({onLogin}:{onLogin:(u:any)=>void}){const[email,setEmail]=useState("");const[password,setPassword]=useState("");const[error,setError]=useState("");const[loading,setLoading]=useState(false);const[needsSetup,setNeedsSetup]=useState(false);const[individual,setIndividual]=useState(false);const[personal,setPersonal]=useState({name:"",email:"",password:""});const[setup,setSetup]=useState({name:"",email:"",password:"",organization:""});useEffect(()=>{fetch("/api/setup").then(r=>r.json()).then(d=>setNeedsSetup(!!d.needsSetup)).catch(()=>{})},[]);const submit=async(e:any)=>{e.preventDefault();setLoading(true);setError("");const r=await fetch("/api/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email,password})});const d=await r.json();setLoading(false);if(r.ok)onLogin(d.user);else setError(d.error||"No fue posible ingresar")};const registerIndividual=async(e:any)=>{e.preventDefault();setLoading(true);setError("");const r=await fetch("/api/register-individual",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(personal)});const d=await r.json();setLoading(false);if(r.ok)onLogin(d.user);else setError(d.error||"No fue posible crear la cuenta")};const activate=async(e:any)=>{e.preventDefault();setLoading(true);setError("");const r=await fetch("/api/setup",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(setup)});const d=await r.json();setLoading(false);if(r.ok){setNeedsSetup(false);setEmail(setup.email);setPassword(setup.password)}else setError(d.error||"No fue posible activar la plataforma")};return <div className="loginPage"><div className="loginCard"><div className="brand loginBrand">Planificación<span>Docente</span></div>{needsSetup?<><small>ACTIVACIÓN INICIAL</small><h1>Crear Superadministrador</h1><p>Esta configuración se habilita una sola vez.</p><form onSubmit={activate}><Field label="Nombre"><input required value={setup.name} onChange={e=>setSetup({...setup,name:e.target.value})}/></Field><Field label="Organización / Sostenedor"><input required value={setup.organization} onChange={e=>setSetup({...setup,organization:e.target.value})}/></Field><Field label="Correo"><input type="email" required value={setup.email} onChange={e=>setSetup({...setup,email:e.target.value})}/></Field><Field label="Contraseña"><input type="password" minLength={8} required value={setup.password} onChange={e=>setSetup({...setup,password:e.target.value})}/></Field>{error&&<div className="loginError">{error}</div>}<button className="primary" disabled={loading}>{loading?"Activando...":"Activar plataforma"}</button></form></>:<><small>GESTIÓN CURRICULAR CON IA</small><h1>{individual?"Crear cuenta docente":"Bienvenido"}</h1><p>{individual?"Tu espacio personal para planificar y evaluar con IA.":"Ingresa con tu cuenta institucional o personal."}</p>{individual?<form onSubmit={registerIndividual}><Field label="Nombre"><input required value={personal.name} onChange={e=>setPersonal({...personal,name:e.target.value})}/></Field><Field label="Correo electrónico"><input type="email" required value={personal.email} onChange={e=>setPersonal({...personal,email:e.target.value})}/></Field><Field label="Contraseña"><input type="password" minLength={8} required value={personal.password} onChange={e=>setPersonal({...personal,password:e.target.value})}/></Field>{error&&<div className="loginError">{error}</div>}<button className="primary" disabled={loading}>{loading?"Creando...":"Crear mi cuenta"}</button><button type="button" onClick={()=>{setIndividual(false);setError("")}}>Ya tengo cuenta</button></form>:<><form onSubmit={submit}><Field label="Correo electrónico"><input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="usuario@institucion.cl"/></Field><Field label="Contraseña"><input type="password" required value={password} onChange={e=>setPassword(e.target.value)} placeholder="Contraseña"/></Field>{error&&<div className="loginError">{error}</div>}<button className="primary" disabled={loading}>{loading?"Ingresando...":"Ingresar"}</button></form><button type="button" onClick={()=>{setIndividual(true);setError("")}}>Crear cuenta docente individual</button></>}</>}<div className="loginFoot">Planificación · Evaluación · Cobertura · Evidencia</div></div></div>}
export default function Home(){const[user,setUser]=useState<any>(null);const[checking,setChecking]=useState(true);const[tab,setTab]=useState("Centro de Mando");const[generated,setGenerated]=useState(false);useEffect(()=>{fetch("/api/session").then(r=>r.json()).then(d=>{if(d.user){setUser(d.user);const paid=new URLSearchParams(window.location.search).get("payment");if(d.user.accountType==="INDIVIDUAL")setTab(paid?"Mi cuenta y suscripción":"Inicio");else if(d.user.role==="DOCENTE")setTab("Planificaciones IA");if(paid)window.history.replaceState({},"",window.location.pathname)}setChecking(false)}).catch(()=>setChecking(false))},[]);const logout=async()=>{await fetch("/api/session",{method:"DELETE"});setUser(null)};if(checking)return <div className="loginPage"><div className="loginCard"><b>Cargando Planificación Docente…</b></div></div>;if(!user)return <Login onLogin={(u)=>{setUser(u);setTab(u.accountType==="INDIVIDUAL"?"Inicio":u.role==="DOCENTE"?"Planificaciones IA":"Centro de Mando")}}/>;const title=tab==="Centro de Mando"?"Seguimiento curricular institucional":tab;return <Shell tab={tab} setTab={setTab} user={user} onLogout={logout}><header><div><small>{tab.toUpperCase()}</small><h1>{title}</h1><p>{tab==="Centro de Mando"?"Del currículum oficial a la evidencia de aprendizaje.":"Herramienta integrada al seguimiento curricular institucional."}</p></div><select><option>2027</option><option>2026</option></select></header>{tab==="Centro de Mando"?<RealDashboard/>:tab==="Cobertura Curricular"?<CoveragePanel/>:tab==="Planificaciones IA"?<Generator type="planificación" generated={generated} setGenerated={setGenerated}/>:tab==="Evaluaciones IA"?<Generator type="evaluación" generated={generated} setGenerated={setGenerated}/>:tab==="Inicio"?<IndividualHome setTab={setTab}/>:tab==="Mi cuenta y suscripción"?<IndividualProfile/>:tab==="Material de apoyo IA"?<SupportMaterials/>:tab==="Mi carpeta"?<MyFolder/>:tab==="Cobertura TP"?<TPDashboard/>:(tab==="Cursos y Asignaturas"||tab==="Mis cursos y asignaturas")?<AcademicPanel/>:tab==="Administración"?<AdminPanel currentUser={user}/>:tab==="Alertas y Mejora"?<ImprovementPanel/>:<article className="panel placeholder"><h2>{tab}</h2><p>Este módulo quedará conectado al Centro de Mando y a la trazabilidad por Objetivos de Aprendizaje.</p><button onClick={()=>setTab(tab==="Cobertura Curricular"?"Planificaciones IA":"Centro de Mando")}>Continuar →</button></article>}<footer><b>Planificado → Implementado → Evaluado → Nivel de logro</b><span>Planificación Docente · Gestión curricular basada en evidencia</span></footer></Shell>};function MyFolder(){const[d,setD]=useState<any>({plannings:[],assessments:[],supportMaterials:[]});const[type,setType]=useState("Todos");const[q,setQ]=useState("");const[course,setCourse]=useState("Todos");const[opened,setOpened]=useState<any>(null);const[msg,setMsg]=useState("");const loadFolder=()=>fetch("/api/my-folder").then(r=>r.json()).then(x=>{if(!x.error)setD(x)}).catch(()=>{});const duplicate=async(x:any)=>{setMsg("Duplicando documento...");const r=await fetch("/api/my-folder/duplicate",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({kind:x.docType==="Planificación"?"planning":x.docType==="Evaluación"?"assessment":"material",id:x.id})});const z=await r.json();if(r.ok){setMsg("✓ Copia creada sin modificar el original");loadFolder()}else setMsg(z.error||"No fue posible duplicar")};useEffect(()=>{loadFolder()},[]);const docs=[...(d.plannings||[]).map((x:any)=>({...x,docType:"Planificación",status:x.implementation?"Implementada":"Borrador"})),...(d.assessments||[]).map((x:any)=>({...x,docType:"Evaluación",status:x.result?"Resultados registrados":"Guardada"})),...(d.supportMaterials||[]).map((x:any)=>({...x,docType:"Material de apoyo",status:"Guardado"}))];const courses=[...new Set(docs.map((x:any)=>x.course?.name).filter(Boolean))] as string[];const shown=docs.filter((x:any)=>(type==="Todos"||x.docType===type)&&(course==="Todos"||x.course?.name===course)&&(!q||String(x.title||"").toLowerCase().includes(q.toLowerCase())||String(x.user?.name||"").toLowerCase().includes(q.toLowerCase())||x.objectives?.some((o:any)=>String(o.objective?.code||"").toLowerCase().includes(q.toLowerCase()))));if(opened){const p=opened.content||{};return <article className="panel documentView"><div className="noPrint panelHead"><button onClick={()=>setOpened(null)}>← Volver a Mi carpeta</button><button className="primary" onClick={()=>window.print()}>Imprimir / Guardar PDF</button></div><div className="doc"><small>{opened.docType.toUpperCase()} · {opened.course?.name||""}</small><h2>{opened.title}</h2><p><b>Docente:</b> {opened.user?.name||""}</p><p><b>OA:</b> {(opened.objectives||[]).map((o:any)=>o.objective?.code).filter(Boolean).join(", ")}</p>{opened.docType==="Material de apoyo"?<><h3>{opened.materialType}</h3>{p.proposito&&<p><b>Propósito:</b> {p.proposito}</p>}{p.instrucciones&&<p>{p.instrucciones}</p>}{(p.secciones||[]).map((s:any,n:number)=><section key={n} className="materialSection"><h3>{s.titulo||"Sección "+(n+1)}</h3><p>{renderValue(s.contenido)}</p>{s.apoyoVisual&&<div className="visualSupport"><b>🖼 Apoyo visual</b><p>{renderValue(s.apoyoVisual)}</p>{s.disposicionVisual&&<small>Disposición: {renderValue(s.disposicionVisual)}</small>}</div>}</section>)}{p.organizadorGrafico&&<section className="visualOrganizer"><h3>Organizador gráfico</h3><p><b>{renderValue(p.organizadorGrafico.tipo)}</b>{p.organizadorGrafico.titulo?` · ${renderValue(p.organizadorGrafico.titulo)}`:""}</p><p>{renderValue(p.organizadorGrafico.elementos)}</p></section>}{p.actividadVisual&&<section className="visualActivity"><h3>Actividad visual</h3><p>{renderValue(p.actividadVisual.consigna)}</p><p><b>Elementos:</b> {renderValue(p.actividadVisual.elementos)}</p>{p.actividadVisual.productoEsperado&&<p><b>Producto esperado:</b> {renderValue(p.actividadVisual.productoEsperado)}</p>}</section>}{p.sugerenciasVisuales?.length>0&&<section><h3>Recursos gráficos sugeridos</h3><div className="visualGrid">{p.sugerenciasVisuales.map((v:any,n:number)=><div className="visualCard" key={n}><b>{renderValue(v.tipo)||"Recurso visual"}</b><p>{renderValue(v.descripcion)}</p>{v.ubicacion&&<small>{renderValue(v.ubicacion)}</small>}</div>)}</div></section>}{p.cierre&&<><h3>Cierre</h3><p>{renderValue(p.cierre)}</p></>}</>:opened.docType==="Planificación"?<><h3>Objetivo de clase</h3><p>{renderValue(p.objetivoClase)}</p><h3>Indicadores</h3><p>{(p.indicadores||[]).join(" · ")}</p>{["inicio","desarrollo","cierre"].map(k=><div key={k}><h3>{k.charAt(0).toUpperCase()+k.slice(1)} {p[k]?.minutos?"· "+p[k].minutos:""}</h3><p><b>Docente:</b> {renderValue(p[k]?.actividadesDocente)}</p><p><b>Estudiantes:</b> {renderValue(p[k]?.actividadesEstudiantes)}</p></div>)}<h3>Evaluación formativa</h3><p>{renderValue(p.evaluacionFormativa)}</p><h3>DUA</h3><p>{(p.dua||[]).join(" · ")}</p>{p.adecuacionesCurriculares?.length>0&&<><h3>Adecuaciones curriculares</h3><p>{renderValue(p.adecuacionesCurriculares)}</p></>}<h3>Recursos y evidencia</h3><p>{(p.recursos||[]).join(" · ")} {p.evidencia?"· "+renderValue(p.evidencia):""}</p></>:<><h3>Instrumento de evaluación</h3>{p.instrucciones&&<p>{p.instrucciones}</p>}<pre style={{whiteSpace:"pre-wrap",fontFamily:"inherit"}}>{JSON.stringify(p,null,2)}</pre></>}</div></article>}return <><div className="tpHero"><div><small>BIBLIOTECA PEDAGÓGICA</small><h2>Mi carpeta</h2><p>Planificaciones, evaluaciones y materiales educativos guardados en un solo lugar.</p></div><div className="tpStat"><b>{docs.length}</b><span>Documentos</span></div></div><article className="panel"><div className="formgrid"><Field label="Buscar"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Título, docente u OA..."/></Field><Field label="Tipo"><select value={type} onChange={e=>setType(e.target.value)}><option>Todos</option><option>Planificación</option><option>Evaluación</option><option>Material de apoyo</option></select></Field><Field label="Curso"><select value={course} onChange={e=>setCourse(e.target.value)}><option>Todos</option>{courses.map(x=><option key={x}>{x}</option>)}</select></Field></div></article>{msg&&<div className={msg.startsWith("✓")?"success":"muted"}>{msg}</div>}<article className="panel"><div className="panelHead"><div><small>DOCUMENTOS</small><h2>{shown.length} encontrados</h2></div></div>{shown.length?shown.map((x:any)=><div className="adminRow" key={x.docType+x.id}><div><b>{x.docType==="Planificación"?"▣":"✓"} {x.title}</b><span>{x.course?.name||"Sin curso"} · {x.user?.name||"Docente"} · {(x.objectives||[]).map((o:any)=>o.objective?.code).filter(Boolean).join(", ")||"Sin OA"}</span></div><div><span className="verified">{x.status}</span><button onClick={()=>setOpened(x)}>Abrir</button><button onClick={()=>duplicate(x)}>Duplicar</button><button onClick={()=>{setOpened(x);setTimeout(()=>window.print(),100)}}>PDF</button><small>{new Date(x.createdAt).toLocaleDateString("es-CL")}</small></div></div>):<p className="muted">No hay documentos que coincidan con los filtros.</p>}</article></>}
function ImprovementPanel(){const[d,setD]=useState<any>({rows:[]});const[courseId,setCourseId]=useState("");const[subject,setSubject]=useState("");const[gap,setGap]=useState("OA planificados pendientes de implementación");const[plan,setPlan]=useState<any>(null);const[msg,setMsg]=useState("");const[loading,setLoading]=useState(false);useEffect(()=>{fetch("/api/coverage").then(r=>r.json()).then(x=>setD(x)).catch(()=>{})},[]);const courses=Array.from(new Map((d.rows||[]).map((x:any)=>[x.courseId,x.course])).entries()) as [string,string][];const subjects=[...new Set((d.rows||[]).filter((x:any)=>x.courseId===courseId).map((x:any)=>x.subject))] as string[];const selected=(d.rows||[]).filter((x:any)=>x.courseId===courseId&&x.subject===subject&&(gap.includes("implementación")?!x.implemented:gap.includes("evaluación")?x.implemented&&!x.evaluated:x.evaluated&&x.achievement==null));const generate=async()=>{if(!selected.length){setMsg("No existen OA con esa brecha en la selección actual.");return}setLoading(true);setMsg("Generando plan de recuperación...");const r=await fetch("/api/improvement-plan",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({courseId,subject,gap,objectiveIds:selected.map((x:any)=>x.oaId)})});const x=await r.json();setLoading(false);if(r.ok){setPlan(x.plan);setMsg("✓ Plan generado desde la brecha curricular real")}else setMsg(x.detail?x.error+": "+x.detail:x.error||"No fue posible generar")};return <div className="builder"><article className="panel form"><div className="step">ALERTAS Y MEJORA</div><h2>Plan de recuperación curricular con IA</h2><p>Selecciona una brecha real registrada en la plataforma. La IA utilizará exclusivamente los OA asociados.</p>{msg&&<div className={msg.startsWith("✓")?"success":"muted"}>{msg}</div>}<Field label="Curso"><select value={courseId} onChange={e=>{setCourseId(e.target.value);setSubject("")}}><option value="">Seleccionar curso</option>{courses.map(([id,n])=><option key={id} value={id}>{n}</option>)}</select></Field><Field label="Asignatura"><select value={subject} onChange={e=>setSubject(e.target.value)}><option value="">Seleccionar asignatura</option>{subjects.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Brecha"><select value={gap} onChange={e=>setGap(e.target.value)}><option>OA planificados pendientes de implementación</option><option>OA implementados pendientes de evaluación</option><option>OA evaluados pendientes de resultado</option></select></Field><div className="oa"><b>{selected.length} OA involucrados</b><span>{selected.map((x:any)=>x.code).join(" · ")||"Sin OA pendientes para esta selección"}</span></div><button className="primary" disabled={loading||!courseId||!subject||!selected.length} onClick={generate}>{loading?"Generando...":"✦ Generar plan de mejora con IA"}</button></article><article className="panel preview"><div className="step">PLAN PROPUESTO</div>{!plan?<div className="empty"><b>El plan aparecerá aquí</b><p>Se construirá desde la evidencia curricular registrada.</p></div>:<div className="doc"><h2>{plan.titulo}</h2><h3>Diagnóstico</h3><p>{plan.diagnostico}</p><h3>Objetivo</h3><p>{plan.objetivo}</p><h3>Acciones</h3>{(plan.acciones||[]).map((x:any,i:number)=><p key={i}><b>{x.accion}</b><br/>{x.responsable} · {x.plazo}<br/><small>Evidencia: {x.evidencia}</small></p>)}<h3>Seguimiento</h3><p>{(plan.seguimiento||[]).join(" · ")}</p><h3>Criterios de cierre</h3><p>{(plan.criteriosCierre||[]).join(" · ")}</p></div>}</article></div>}
function CoveragePanel(){const[d,setD]=useState<any>({rows:[]});const[e,setE]=useState("");const[course,setCourse]=useState("");const[subject,setSubject]=useState("");useEffect(()=>{fetch("/api/coverage").then(async r=>{const x=await r.json();if(r.ok)setD(x);else setE(x.error||"No fue posible cargar")}).catch(()=>setE("No fue posible cargar"))},[]);const courses=[...new Set(d.rows.map((x:any)=>x.course))] as string[];const subjects=[...new Set(d.rows.filter((x:any)=>!course||x.course===course).map((x:any)=>x.subject))] as string[];const rows=d.rows.filter((x:any)=>(!course||x.course===course)&&(!subject||x.subject===subject));return <article className="panel matrix"><div className="panelHead"><div><small>TRAZABILIDAD POR OBJETIVO DE APRENDIZAJE</small><h2>Cobertura curricular real</h2><p>Curso → Asignatura → OA → estado → logro.</p></div></div>{e&&<p>{e}</p>}<div className="formgrid"><Field label="Curso"><select value={course} onChange={e=>{setCourse(e.target.value);setSubject("")}}><option value="">Todos</option>{courses.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Asignatura"><select value={subject} onChange={e=>setSubject(e.target.value)}><option value="">Todas</option>{subjects.map(x=><option key={x}>{x}</option>)}</select></Field></div><table><thead><tr><th>Curso</th><th>Asignatura</th><th>OA</th><th>Planificado</th><th>Implementado</th><th>Evaluado</th><th>Logro</th></tr></thead><tbody>{rows.map((r:any)=><tr key={r.courseId+"-"+r.oaId}><th>{r.course}</th><td>{r.subject}</td><td title={r.text}><b>{r.code}</b></td><td>{r.planned?"✓":"—"}</td><td>{r.implemented?"✓":"—"}</td><td>{r.evaluated?"✓":"—"}</td><td>{r.achievement==null?"—":r.achievement+"%"}</td></tr>)}</tbody></table>{!rows.length&&<p className="muted">Aún no existen OA con trazabilidad para los filtros seleccionados.</p>}</article>}
function RealDashboard(){const[d,setD]=useState<any>(null);const[e,setE]=useState("");useEffect(()=>{fetch("/api/dashboard").then(async r=>{const x=await r.json();if(r.ok)setD(x);else setE(x.error||"No fue posible cargar")}).catch(()=>setE("No fue posible cargar"))},[]);if(e)return <article className="panel"><h2>Centro de Mando</h2><p>{e}</p></article>;if(!d)return <article className="panel"><h2>Centro de Mando</h2><p>Cargando datos curriculares reales…</p></article>;const k=d.kpis;return <><div className="cards">{[["OA PLANIFICADOS",k.planned,"Con trazabilidad"],["OA IMPLEMENTADOS",k.implemented,"Registrados como trabajados"],["OA EVALUADOS",k.evaluated,"Con evidencia evaluativa"],["LOGRO PROMEDIO",k.achievement==null?"—":k.achievement+"%","Resultados registrados"],["CURSOS",k.courses,"Año "+d.year]].map((x:any)=><article key={x[0]}><small>{x[0]}</small><strong>{x[1]}</strong><p>{x[2]}</p></article>)}</div><div className="grid"><article className="panel"><div className="panelHead"><div><small>TRAZABILIDAD REAL</small><h2>Planificado → Implementado → Evaluado</h2></div></div><p>Los indicadores se calculan desde registros reales de docentes y evaluaciones.</p></article><article className="panel alerts"><small>ALERTAS CURRICULARES</small><h2>Seguimiento requerido</h2>{(d.alerts||[]).length?(d.alerts||[]).map((a:any,i:number)=><div key={i}><b>{a.title}</b><p>{a.action}</p></div>):<div><b>Sin brechas de trazabilidad registradas</b><p>Los OA registrados completan su secuencia disponible.</p></div>}</article></div><article className="panel matrix"><div className="panelHead"><div><small>DETALLE POR CURSO</small><h2>Seguimiento curricular</h2></div></div><table><thead><tr><th>Curso</th><th>OA planificados</th><th>OA implementados</th><th>OA evaluados</th><th>Implementación</th><th>Evaluación</th></tr></thead><tbody>{d.rows.map((r:any)=><tr key={r.id}><th>{r.course}</th><td>{r.plannedOA}</td><td>{r.implementedOA}</td><td>{r.evaluatedOA}</td><Cell n={r.implementationPct}/><Cell n={r.evaluationPct}/></tr>)}</tbody></table>{!d.rows.length&&<p className="muted">Aún no existen cursos con información curricular para este año.</p>}</article></>}
function Generator({type,generated,setGenerated}:{type:string,generated:boolean,setGenerated:(x:boolean)=>void}){const evaluation=type==="evaluación";if(evaluation)return <RealAssessmentGenerator/>;return <RealPlanningGenerator/>}
function StructuredAssessmentInstrument({p}:{p:any}){const checklist=p.listaCotejo;const scale=p.escalaValoracion;const observation=p.pautaObservacion;const anecdotal=p.registroAnecdotico;const notebook=p.pautaCuaderno;const portfolio=p.portafolio;
 const matrix=(title:string,levels:any[],rows:any[],kind:string)=><section className="structuredInstrument"><h3>{title}</h3><div className="instrumentTableWrap"><table className="instrumentTable"><thead><tr><th>Indicadores / criterios</th>{levels.map((x:any,i:number)=><th key={i}>{renderValue(x?.nombre??x)}</th>)}<th>Observaciones</th></tr></thead><tbody>{rows.map((r:any,i:number)=><tr key={i}><th>{renderValue(r.indicador||r.criterio)}{r.oa&&<small>{renderValue(r.oa)}</small>}</th>{levels.map((x:any,j:number)=><td key={j}>{kind==="scale"?renderValue(Array.isArray(r.descriptores)?r.descriptores[j]:r.descriptores?.[x?.nombre??x]):<span className="checkBox"></span>}</td>)}<td></td></tr>)}</tbody></table></div></section>;
 if(checklist?.indicadores?.length)return matrix("Lista de cotejo",checklist.categorias||["Sí","No"],checklist.indicadores,"check");
 if(scale?.indicadores?.length)return matrix("Escala de valoración",scale.niveles||[],scale.indicadores,"scale");
 if(observation?.indicadores?.length)return matrix("Pauta de observación",observation.escala||[],observation.indicadores,"check");
 if(notebook?.indicadores?.length)return matrix("Pauta de valoración del cuaderno",notebook.escala||[],notebook.indicadores,"check");
 if(anecdotal)return <section className="structuredInstrument"><h3>Registro anecdótico</h3><div className="anecdotalGrid">{[["Fecha",anecdotal.fecha],["Contexto",anecdotal.contexto],["Situación observada",anecdotal.situacionObservada],["Descripción objetiva",anecdotal.descripcionObjetiva],["Interpretación pedagógica",anecdotal.interpretacionPedagogica],["OA relacionado",anecdotal.oaRelacionado],["Acciones de seguimiento",anecdotal.accionesSeguimiento],["Observaciones",anecdotal.observaciones]].map(([k,v],i)=><div className="anecdotalField" key={i}><b>{k}</b><p>{renderValue(v)||" "}</p></div>)}</div></section>;
 if(portfolio?.evidencias?.length)return <section className="structuredInstrument"><h3>Portafolio de evidencias</h3><div className="instrumentTableWrap"><table className="instrumentTable"><thead><tr><th>Evidencia</th><th>OA</th><th>Criterio</th><th>Fecha / hito</th></tr></thead><tbody>{portfolio.evidencias.map((e:any,i:number)=><tr key={i}><td>{renderValue(e.evidencia)}</td><td>{renderValue(e.oa)}</td><td>{renderValue(e.criterio)}</td><td>{renderValue(e.fechaEntrega)}</td></tr>)}</tbody></table></div><div className="instrumentNotes"><b>Reflexión del estudiante</b><p>{renderValue(portfolio.reflexionEstudiante)}</p><b>Retroalimentación docente</b><p>{renderValue(portfolio.retroalimentacionDocente)}</p></div></section>;
 return null}
function RealAssessmentGenerator(){const[data,setData]=useState<any>({courses:[],objectives:[],tpModules:[],aiReady:false});const[courseId,setCourseId]=useState("");const[subject,setSubject]=useState("");const[includeImages,setIncludeImages]=useState(true);const[personalStage,setPersonalStage]=useState("");const[personalLevel,setPersonalLevel]=useState("");const[specialty,setSpecialty]=useState("");const[moduleId,setModuleId]=useState("");const[selected,setSelected]=useState<string[]>([]);const[type,setType]=useState("SUMMATIVE");const[instrument,setInstrument]=useState("Prueba mixta");const[generationMode,setGenerationMode]=useState<"AI"|"TEACHER">("AI");const[itemComposition,setItemComposition]=useState([{type:"Selección múltiple",count:10},{type:"Verdadero/Falso",count:5},{type:"Desarrollo",count:5}]);const[questions,setQuestions]=useState(20);const[totalScore,setTotalScore]=useState(40);const[difficulty,setDifficulty]=useState(60);const[itemScores,setItemScores]=useState<number[]>(Array(20).fill(2));const[duration,setDuration]=useState("60 minutos");const[instructions,setInstructions]=useState("");const[adaptationsRequired,setAdaptationsRequired]=useState(false);const[adaptationsDescription,setAdaptationsDescription]=useState("");const[header,setHeader]=useState({schoolName:"",department:"",schoolYear:"2026",assessmentLabel:"EVALUACIÓN ESCRITA",teacherName:""});const[result,setResult]=useState<any>(null);const[editing,setEditing]=useState(false);const[editJson,setEditJson]=useState("");const[printMode,setPrintMode]=useState<"student"|"key">("student");const[resultForm,setResultForm]=useState({achievement:"",students:"",notes:""});const[msg,setMsg]=useState("");const[loading,setLoading]=useState(false);
const load=async()=>{const r=await fetch("/api/ai-assessment");const d=await r.json();if(r.ok){setData(d);if(!courseId&&d.courses?.[0]){setCourseId(d.courses[0].id);setSubject(d.courses[0].teachingAssignments?.[0]?.subject||curricularSubjects(d.courses[0].level||"")?.[0]||"")}}else setMsg(d.error||"No fue posible cargar")};useEffect(()=>{load()},[]);
const individual=data.accountType==="INDIVIDUAL";const personalLevels=[...new Set((data.objectives||[]).map((x:any)=>x.level).filter(Boolean))] as string[];const personalStages=[...new Set(personalLevels.map(educationStage))];const choosePersonalLevel=async(level:string)=>{setPersonalLevel(level);setSubject("");setSelected([]);setResult(null);if(!level){setCourseId("");return}setMsg("Preparando curso personal...");const r=await fetch("/api/personal-course",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({level})});const x=await r.json();if(!r.ok){setMsg(x.error||"No fue posible seleccionar el curso");return}setCourseId(x.course.id);setData((d:any)=>({...d,courses:[...(d.courses||[]).filter((q:any)=>q.id!==x.course.id),x.course]}));setMsg("")};const course=data.courses?.find((x:any)=>x.id===courseId);const isTP=course?.track==="TP";const assignedSubs=Array.from(new Set((course?.teachingAssignments||[]).map((x:any)=>x.subject))) as string[];const oaSubs=[...new Set((data.objectives||[]).filter((x:any)=>x.level===course?.level).map((x:any)=>x.subject).filter(Boolean))] as string[];const subs=(individual?[...new Set([...oaSubs,...curricularSubjects(course?.level||"")])]:assignedSubs.length?assignedSubs:curricularSubjects(course?.level||"")) as string[];const tpSpecialtiesAvailable=Array.from(new Set((data.tpModules||[]).filter((x:any)=>!course?.level||x.level===course.level).map((x:any)=>x.specialty))) as string[];const modules=(data.tpModules||[]).filter((x:any)=>x.specialty===specialty&&(!course?.level||x.level===course.level));const selectedModule=modules.find((x:any)=>x.id===moduleId);const objectives=isTP?(selectedModule?.objectives||[]).map((x:any)=>x.objective):(data.objectives||[]).filter((x:any)=>x.level===course?.level&&x.subject===subject);
const scoreSum=itemScores.slice(0,questions).reduce((a,v)=>a+(Number(v)||0),0);const passingScore=(totalScore*difficulty/100).toFixed(1);const changeQuestions=(n:number)=>{const q=Math.max(1,Math.min(60,n));setQuestions(q);setItemScores(old=>Array.from({length:q},(_,i)=>old[i]??1))};const changeCourse=(id:string)=>{setCourseId(id);const q=data.courses?.find((x:any)=>x.id===id);setSubject(q?.teachingAssignments?.[0]?.subject||curricularSubjects(q?.level||"")?.[0]||"");setSelected([]);setSpecialty("");setModuleId("");setResult(null)};
const generate=async()=>{if(!data.aiReady){setMsg("La IA no está disponible en el servidor. Revisa la configuración de OPENAI_API_KEY.");return}if(!courseId||(!isTP&&!subject)||(isTP&&!moduleId)||!selected.length){setMsg(isTP?"Selecciona curso, especialidad, módulo y al menos un OA.":"Selecciona curso, asignatura y al menos un OA.");return}if(adaptationsRequired&&!adaptationsDescription.trim()){setMsg("Seleccionaste adecuaciones PIE. Describe las adecuaciones requeridas antes de generar.");return}setLoading(true);setMsg("Generando evaluación con IA...");const r=await fetch("/api/ai-assessment",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({courseId,subject:isTP?(selectedModule?.name||subject):subject,moduleId:isTP?moduleId:undefined,objectiveIds:selected,type,instrument,generationMode,itemComposition,questions,totalScore,difficulty,itemScores,duration,instructions,header,includeImages,adaptationsRequired,adaptationsDescription})});const d=await r.json();setLoading(false);if(r.ok){setResult(d.assessment);setEditJson(JSON.stringify(d.assessment.content,null,2));setMsg("✓ Evaluación generada y guardada")}else setMsg(d.detail?d.error+": "+d.detail:d.error||"No fue posible generar")};
const saveEdit=async()=>{try{const content=JSON.parse(editJson);const r=await fetch("/api/ai-assessment",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:result.id,title:content.titulo||result.title,content})});const d=await r.json();if(r.ok){setResult({...result,title:d.assessment.title,content:d.assessment.content});setEditing(false);setMsg("✓ Correcciones guardadas")}else setMsg(d.error||"No fue posible guardar")}catch{setMsg("El contenido editado no tiene un formato válido")}};
const evaluatedOAs=selected.map((id:string)=>objectives.find((o:any)=>o.id===id)).filter(Boolean);const evaluatedOAText=evaluatedOAs.map((o:any)=>`${o.code} · ${o.text}`).join(" | ");
const saveResult=async()=>{if(!result)return;const r=await fetch("/api/assessment-result",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({assessmentId:result.id,achievement:Number(resultForm.achievement),students:resultForm.students===""?null:Number(resultForm.students),notes:resultForm.notes})});const d=await r.json();if(r.ok){setResult({...result,result:d.result});setMsg("✓ Resultado registrado y Centro de Mando actualizado");load()}else setMsg(d.error||"No fue posible registrar el resultado")};const print=(mode:"student"|"key")=>{setPrintMode(mode);setTimeout(()=>window.print(),100)};const p=result?.content;
return <div className="builder"><article className="panel form"><div className="step">1 · EVALUACIÓN ALINEADA AL CURRÍCULUM</div><h2>Crear evaluación con IA</h2>{msg&&<div className={msg.startsWith("✓")?"success":"muted"}>{msg}</div>}<div className="formgrid">{individual?<><Field label="Nivel de enseñanza"><select value={personalStage} onChange={e=>{setPersonalStage(e.target.value);setPersonalLevel("");setCourseId("");setSubject("");setSelected([])}}><option value="">Seleccionar nivel</option>{personalStages.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Curso"><select value={personalLevel} onChange={e=>choosePersonalLevel(e.target.value)}><option value="">Seleccionar curso</option>{personalLevels.filter(x=>educationStage(x)===personalStage).map(x=><option key={x}>{x}</option>)}</select></Field></>:<Field label="Curso"><select value={courseId} onChange={e=>changeCourse(e.target.value)}><option value="">Seleccionar curso</option>{data.courses?.map((x:any)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field>}<Field label="Asignatura"><select value={subject} onChange={e=>{setSubject(e.target.value);setSelected([])}}><option value="">Seleccionar asignatura</option>{subs.map(x=><option key={x}>{x}</option>)}</select></Field></div>{isTP&&<div className="formgrid"><Field label="Especialidad TP"><select value={specialty} onChange={e=>{setSpecialty(e.target.value);setModuleId("");setSelected([])}}><option value="">Seleccionar especialidad</option>{tpSpecialtiesAvailable.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Módulo oficial"><select value={moduleId} onChange={e=>{setModuleId(e.target.value);setSelected([])}}><option value="">Seleccionar módulo</option>{modules.map((m:any)=><option key={m.id} value={m.id}>{m.level} · {m.name}</option>)}</select></Field></div>}<Field label="Objetivos de Aprendizaje"><div className="oaList">{objectives.length?objectives.map((oa:any)=><div className="oa" key={oa.id}><b>{oa.code}</b><span>{oa.text}</span><input type="checkbox" checked={selected.includes(oa.id)} onChange={()=>setSelected(selected.includes(oa.id)?selected.filter(x=>x!==oa.id):[...selected,oa.id])}/></div>):<div className="oa"><span>No hay OA oficiales cargados para esta combinación.</span></div>}</div></Field><div className="formgrid"><Field label="Modalidad de generación"><select value={generationMode} onChange={e=>setGenerationMode(e.target.value as "AI"|"TEACHER")}><option value="AI">Automática con IA</option><option value="TEACHER">Configuración docente</option></select></Field><Field label="Tipo"><select value={type} onChange={e=>setType(e.target.value)}><option value="SUMMATIVE">Sumativa</option><option value="FORMATIVE">Formativa</option><option value="DIAGNOSTIC">Diagnóstica</option></select></Field><Field label="Instrumento"><select value={instrument} onChange={e=>setInstrument(e.target.value)}><optgroup label="Instrumentos basados en la observación"><option>Lista de cotejo</option><option>Escala de valoración</option><option>Registro anecdótico</option><option>Pauta de observación</option></optgroup><optgroup label="Instrumentos de desempeño y análisis de productos"><option>Rúbrica</option><option>Portafolio</option><option>Cuaderno del estudiante</option></optgroup><optgroup label="Pruebas formales y escritas"><option>Prueba mixta</option><option>Prueba de respuesta abierta</option><option>Prueba objetiva</option><option>Mapa conceptual o mental</option></optgroup><optgroup label="Instrumentos complementarios"><option>Autoevaluación</option><option>Coevaluación</option><option>Ticket de salida</option></optgroup></select></Field></div>{generationMode==="TEACHER"&&<div className="panel" style={{margin:"12px 0",padding:"14px"}}><b>Composición de ítems definida por el docente</b><p className="muted">Indica cuántos ítems de cada tipo deseas. La IA respetará esta estructura.</p>{itemComposition.map((row,i)=><div className="formgrid" key={i}><Field label={`Tipo ${i+1}`}><select value={row.type} onChange={e=>setItemComposition(old=>old.map((x,j)=>j===i?{...x,type:e.target.value}:x))}><option>Selección múltiple</option><option>Verdadero/Falso</option><option>Respuesta breve</option><option>Desarrollo</option><option>Resolución de problemas</option><option>Análisis de casos</option><option>Completación</option><option>Términos pareados</option></select></Field><Field label="Cantidad"><input type="number" min="0" max="60" value={row.count} onChange={e=>setItemComposition(old=>old.map((x,j)=>j===i?{...x,count:Math.max(0,Number(e.target.value)||0)}:x))}/></Field></div>)}<button onClick={()=>setItemComposition(old=>[...old,{type:"Respuesta breve",count:1}])}>+ Agregar tipo de ítem</button><p className="muted">Total configurado: {itemComposition.reduce((a,x)=>a+x.count,0)} ítems.</p></div>}<div className="formgrid"><Field label="Cantidad de ítems"><input type="number" min="1" max="60" value={questions} onChange={e=>changeQuestions(Number(e.target.value))}/></Field><Field label="Duración"><input value={duration} onChange={e=>setDuration(e.target.value)}/></Field></div>{type==="SUMMATIVE"&&<div className="panel" style={{margin:"12px 0",padding:"14px"}}><b>Configuración de puntaje y exigencia</b><div className="formgrid"><Field label="Puntaje total"><input type="number" min="1" value={totalScore} onChange={e=>setTotalScore(Math.max(1,Number(e.target.value)||1))}/></Field><Field label="Porcentaje de exigencia"><input type="number" min="1" max="100" value={difficulty} onChange={e=>setDifficulty(Math.max(1,Math.min(100,Number(e.target.value)||60)))}/></Field></div><small className="sourceTag">Puntaje de aprobación: {passingScore} pts. · Suma actual de ítems: {scoreSum} / {totalScore} pts.</small><div className="formgrid">{Array.from({length:questions},(_,i)=><Field key={i} label={`Ítem ${i+1}`}><input type="number" min="0" step="0.5" value={itemScores[i]??0} onChange={e=>setItemScores(old=>old.map((v,j)=>j===i?Math.max(0,Number(e.target.value)||0):v))}/></Field>)}</div>{scoreSum!==totalScore&&<div className="muted">La suma de puntajes por ítem debe ser igual al puntaje total.</div>}</div>}<div className="panel" style={{margin:"12px 0",padding:"14px"}}><b>Encabezado de la evaluación</b><p className="muted">Estos datos aparecerán en el instrumento y puedes cambiarlos en cada evaluación.</p><div className="formgrid"><Field label="Nombre colegio"><input value={header.schoolName} onChange={e=>setHeader({...header,schoolName:e.target.value})} placeholder="Ej: Complejo Educativo..."/></Field><Field label="Departamento"><input value={header.department} onChange={e=>setHeader({...header,department:e.target.value})} placeholder="Ej: Lenguaje / Ciencias"/></Field><Field label="Año escolar"><input value={header.schoolYear} onChange={e=>setHeader({...header,schoolYear:e.target.value})} placeholder="2026"/></Field><Field label="Tipo / título"><input value={header.assessmentLabel} onChange={e=>setHeader({...header,assessmentLabel:e.target.value})} placeholder="EVALUACIÓN ESCRITA"/></Field><Field label="Profesor(a)"><input value={header.teacherName} onChange={e=>setHeader({...header,teacherName:e.target.value})} placeholder="Nombre del profesor(a)"/></Field></div></div><div className="panel pieAdaptations" style={{margin:"12px 0",padding:"14px"}}><b>Adecuaciones de la evaluación · PIE</b><p className="muted">Define si este instrumento requiere adecuaciones para responder a las necesidades de estudiantes PIE.</p><div className="formgrid"><Field label="¿Requiere adecuaciones?"><select value={adaptationsRequired?"YES":"NO"} onChange={e=>{const yes=e.target.value==="YES";setAdaptationsRequired(yes);if(!yes)setAdaptationsDescription("")}}><option value="NO">No</option><option value="YES">Sí</option></select></Field></div>{adaptationsRequired&&<Field label="Describa las adecuaciones requeridas"><textarea value={adaptationsDescription} onChange={e=>setAdaptationsDescription(e.target.value)} placeholder="Ej.: instrucciones simplificadas, mayor tiempo, apoyo visual, reducción o segmentación de ítems, lectura mediada, formato de respuesta alternativo..."/></Field>}</div><Field label="Indicaciones para la IA"><textarea value={instructions} onChange={e=>setInstructions(e.target.value)}/></Field><label className="imageToggle"><input type="checkbox" checked={includeImages} onChange={e=>setIncludeImages(e.target.checked)}/><span>Incluir ilustraciones IA cuando una pregunta las necesite</span></label><button type="button" className="primary" disabled={loading} onClick={generate}>{loading?"Generando evaluación…":"✦ Generar evaluación con IA"}</button><p className="muted">La IA validará y ajustará automáticamente la distribución de puntajes y la estructura del instrumento cuando corresponda.</p></article><article className="panel preview"><div className="step">2 · INSTRUMENTO GENERADO</div>{!p?<div className="empty"><b>La evaluación aparecerá aquí</b><p>Quedará vinculada a sus OA y podrá corregirse antes de imprimir.</p></div>:<><div className="success noPrint">✓ Guardada · trazabilidad OA activa</div><div className="actions noPrint"><button onClick={()=>{setEditing(!editing);setEditJson(JSON.stringify(result.content,null,2))}}>{editing?"Cancelar edición":"Corregir evaluación"}</button><button onClick={()=>print("student")}>PDF estudiante</button><button onClick={()=>print("key")}>PDF pauta docente</button></div><div className="noPrint panel" style={{margin:"12px 0",padding:"14px"}}><b>Registrar resultados de la evaluación</b><div className="formgrid"><Field label="% de logro del curso"><input type="number" min="0" max="100" value={resultForm.achievement} onChange={e=>setResultForm({...resultForm,achievement:e.target.value})}/></Field><Field label="Estudiantes evaluados"><input type="number" min="0" value={resultForm.students} onChange={e=>setResultForm({...resultForm,students:e.target.value})}/></Field></div><Field label="Observaciones"><textarea value={resultForm.notes} onChange={e=>setResultForm({...resultForm,notes:e.target.value})}/></Field><button className="primary" disabled={resultForm.achievement===""} onClick={saveResult}>{result.result?"Actualizar resultado":"Registrar resultado"}</button>{result.result&&<small className="sourceTag">Resultado actual: {result.result.achievement}% de logro</small>}</div>{editing?<div className="noPrint"><Field label="Editor de la evaluación"><textarea style={{minHeight:"520px",fontFamily:"monospace"}} value={editJson} onChange={e=>setEditJson(e.target.value)}/></Field><button className="primary" onClick={saveEdit}>Guardar correcciones</button></div>:<div className="assessmentPrint"><div className={printMode==="student"?"studentPrint":"studentPrint screenOnly"}><div style={{textAlign:"center",marginBottom:14}}><b>{renderValue(p.encabezado?.schoolName)||"Nombre colegio"}</b><div>{renderValue(p.encabezado?.department)||"Departamento"}</div><div><b>Año Escolar:</b> {renderValue(p.encabezado?.schoolYear)||"2026"}</div><h2>{renderValue(p.encabezado?.assessmentLabel)||"EVALUACIÓN ESCRITA"} DE {subject||"ASIGNATURA"}</h2></div><div className="printStudentData"><div className="studentDataTitle"><b>Información del Estudiante</b></div><div className="studentDataGrid"><div className="studentDataCell"><b>Nombre:</b><span className="writeLine"></span></div><div className="studentDataCell"><b>Curso:</b><span>{result.course?.name||course?.name}</span></div><div className="studentDataCell"><b>Fecha:</b><span className="writeLine short"></span></div><div className="studentDataCell"><b>Puntaje Total:</b><span>{p.configuracionSumativa?.puntajeTotal??totalScore} pts.</span></div><div className="studentDataCell"><b>Profesor(a):</b><span>{renderValue(p.encabezado?.teacherName)||"________________________"}</span></div><div className="studentDataCell"><b>Puntaje Obtenido:</b><span className="writeLine short"></span></div><div className="studentDataCell"><b>Nota:</b><span className="writeLine short"></span></div><div className="studentDataCell"><b>Exigencia:</b><span>{p.configuracionSumativa?.porcentajeExigencia??difficulty}%</span></div></div></div><div className="doc">{p.adecuaciones?.requerido&&<section className="assessmentAdaptations"><h3>Adecuaciones de la evaluación · PIE</h3><p><b>Requiere adecuaciones:</b> Sí</p><p><b>Adecuaciones solicitadas:</b> {renderValue(p.adecuaciones.descripcion)}</p>{p.adecuaciones.aplicacionesRealizadas?.length>0&&<p><b>Aplicadas en el instrumento:</b> {renderValue(p.adecuaciones.aplicacionesRealizadas)}</p>}</section>}<h3>Objetivos de Aprendizaje evaluados</h3>{evaluatedOAs.length>0?evaluatedOAs.map((o:any)=><p key={o.id}><b>{renderValue(o.code)}</b> · {renderValue(o.text)}</p>):<p>{evaluatedOAText||"OA seleccionados para esta evaluación."}</p>}<h3>Instrucciones</h3><p>{renderValue(p.instrucciones)}</p>{p.criterios?.length>0&&<><h3>Criterios del instrumento</h3>{p.criterios.map((x:any,i:number)=><p key={i}>{typeof x==="string"?x:JSON.stringify(x)}</p>)}</>}{p.escala?.length>0&&<><h3>Escala</h3><p>{p.escala.map((x:any)=>typeof x==="string"?x:JSON.stringify(x)).join(" · ")}</p></>}<StructuredAssessmentInstrument p={p}/>{p.rubricaMatriz?.niveles?.length>0&&p.rubricaMatriz?.criterios?.length>0?<><h3>Rúbrica de evaluación</h3><div className="rubricTableWrap"><table className="rubricTable"><thead><tr><th>Criterios / indicadores</th>{p.rubricaMatriz.niveles.map((n:any,i:number)=><th key={i}>{renderValue(n.nombre)}{n.puntaje!==undefined&&n.puntaje!==null?<small>{renderValue(n.puntaje)} pts.</small>:null}</th>)}</tr></thead><tbody>{p.rubricaMatriz.criterios.map((cr:any,r:number)=><tr key={r}><th className="rubricCriterion">{renderValue(cr.criterio)}{cr.oa&&<small>{renderValue(cr.oa)}</small>}</th>{p.rubricaMatriz.niveles.map((_:any,col:number)=><td key={col}>{renderValue(Array.isArray(cr.descriptores)?cr.descriptores[col]:cr.descriptores?.[p.rubricaMatriz.niveles[col]?.nombre]??cr.descriptores?.[col])}</td>)}</tr>)}</tbody></table></div></>:<><h3>Ítems / indicadores</h3>{(p.items||[]).map((x:any)=><div key={x.numero}><p><b>{renderValue(x.numero)}. {renderValue(x.enunciado)}</b> ({renderValue(x.puntaje)} pts.)</p>{x.alternativas?.map((a:any,i:number)=><p key={i}>{typeof a==="object"&&a?.letra?`${renderValue(a.letra)}) ${renderValue(a.texto)}`:`${String.fromCharCode(65+i)}) ${renderValue(a)}`}</p>)}</div>)}</>}</div></div><div className={printMode==="key"?"keyPrint":"keyPrint screenOnly"}><div style={{textAlign:"center",marginBottom:14}}><b>{renderValue(p.encabezado?.schoolName)||"Nombre colegio"}</b><div>{renderValue(p.encabezado?.department)||"Departamento"}</div><div><b>Año Escolar:</b> {renderValue(p.encabezado?.schoolYear)||"2026"}</div><h2>Pauta de corrección · {renderValue(p.encabezado?.assessmentLabel)||"EVALUACIÓN"} DE {subject||"ASIGNATURA"}</h2></div><div className="printStudentData" style={{lineHeight:2}}><div><b>Profesor(a):</b> {renderValue(p.encabezado?.teacherName)||"________________________"} &nbsp; <b>Asignatura:</b> {subject||"________________________"}</div><div><b>Curso:</b> {result.course?.name||course?.name} &nbsp; <b>Año:</b> {renderValue(p.encabezado?.schoolYear)||"2026"}</div></div><div className="doc">{p.adecuaciones?.requerido&&<section className="assessmentAdaptations"><h3>Adecuaciones de la evaluación · PIE</h3><p><b>Requiere adecuaciones:</b> Sí</p><p><b>Adecuaciones solicitadas:</b> {renderValue(p.adecuaciones.descripcion)}</p>{p.adecuaciones.aplicacionesRealizadas?.length>0&&<p><b>Aplicadas en el instrumento:</b> {renderValue(p.adecuaciones.aplicacionesRealizadas)}</p>}</section>}<h3>Objetivos de Aprendizaje evaluados</h3>{evaluatedOAs.map((o:any)=><p key={o.id}><b>{renderValue(o.code)}</b> · {renderValue(o.text)}</p>)}{p.configuracionSumativa&&<p><b>Puntaje total:</b> {p.configuracionSumativa.puntajeTotal} · <b>Exigencia:</b> {p.configuracionSumativa.porcentajeExigencia}% · <b>Puntaje aprobación:</b> {p.configuracionSumativa.puntajeAprobacion}</p>}<h3>Tabla de especificaciones</h3>{(p.tablaEspecificaciones||[]).map((x:any,i:number)=><p key={i}><b>{renderValue(x.oa)}</b> · {renderValue(x.habilidad)} · ítems {renderValue(x.items)} · {renderValue(x.puntaje)} pts.</p>)}<StructuredAssessmentInstrument p={p}/>{p.rubricaMatriz?.niveles?.length>0&&p.rubricaMatriz?.criterios?.length>0?<><h3>Rúbrica de evaluación</h3><div className="rubricTableWrap"><table className="rubricTable"><thead><tr><th>Criterios / indicadores</th>{p.rubricaMatriz.niveles.map((n:any,i:number)=><th key={i}>{renderValue(n.nombre)}{n.puntaje!==undefined&&n.puntaje!==null?<small>{renderValue(n.puntaje)} pts.</small>:null}</th>)}</tr></thead><tbody>{p.rubricaMatriz.criterios.map((cr:any,r:number)=><tr key={r}><th className="rubricCriterion">{renderValue(cr.criterio)}{cr.oa&&<small>{renderValue(cr.oa)}</small>}</th>{p.rubricaMatriz.niveles.map((_:any,col:number)=><td key={col}>{renderValue(Array.isArray(cr.descriptores)?cr.descriptores[col]:cr.descriptores?.[p.rubricaMatriz.niveles[col]?.nombre]??cr.descriptores?.[col])}</td>)}</tr>)}</tbody></table></div></>:<><h3>Respuestas y pauta</h3>{(p.items||[]).map((x:any)=><p key={x.numero}><b>{x.numero}.</b> {renderValue(x.respuestaCorrecta)||"Según pauta"} · {renderValue(x.puntaje)} pts. · {renderValue(x.oa)}</p>)}</>}{(Array.isArray(p.pautaCorreccion)?p.pautaCorreccion:p.pautaCorreccion?[p.pautaCorreccion]:[]).map((x:any,i:number)=><p key={i}>{renderValue(x)}</p>)}<h3>Niveles de logro</h3>{(p.nivelesLogro||[]).map((x:any,i:number)=><p key={i}><b>{renderValue(x.nivel)}</b> · {renderValue(x.desde)}–{renderValue(x.hasta)} · {renderValue(x.descripcion)}</p>)}</div></div></div>}</>}</article></div>}
function downloadPlanningPdf(result:any){if(!result)return;const p=result.content||{};const esc=(s:any)=>String(s??"").replace(/[&<>]/g,(m)=>({"&":"&amp;","<":"&lt;",">":"&gt;"} as any)[m]);const moments=["inicio","desarrollo","cierre"].map(k=>`<section><h2>${k.charAt(0).toUpperCase()+k.slice(1)} ${p[k]?.minutos?"· "+esc(p[k].minutos):""}</h2><p><b>Actividades del docente:</b> ${esc(p[k]?.actividadesDocente)}</p><p><b>Actividades de los estudiantes:</b> ${esc(p[k]?.actividadesEstudiantes)}</p></section>`).join("");const html=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(result.title)}</title><style>@page{size:A4;margin:16mm}body{font-family:Arial,sans-serif;color:#172033;font-size:11pt;line-height:1.45}h1{font-size:20pt;margin-bottom:4px}h2{font-size:14pt;border-bottom:1px solid #ccd5e0;padding-bottom:4px;margin-top:18px}.meta{background:#f3f6f9;padding:10px;border-radius:8px}.oa{margin:5px 0}ul{padding-left:20px}</style></head><body><h1>${esc(result.title)}</h1><div class="meta"><b>Curso:</b> ${esc(result.course?.name||"")}<br><b>Objetivos de Aprendizaje:</b> ${(result.objectives||[]).map((o:any)=>esc(o.objective?.code)+" · "+esc(o.objective?.text)).join("<br>")}</div><h2>Objetivo de clase</h2><p>${esc(p.objetivoClase)}</p><h2>Indicadores</h2><ul>${(p.indicadores||[]).map((x:any)=>"<li>"+esc(x)+"</li>").join("")}</ul>${moments}<h2>Evaluación formativa</h2><p>${esc(p.evaluacionFormativa)}</p><h2>Recursos</h2><ul>${(p.recursos||[]).map((x:any)=>"<li>"+esc(x)+"</li>").join("")}</ul><h2>DUA</h2><ul>${(p.dua||[]).map((x:any)=>"<li>"+esc(x)+"</li>").join("")}</ul>${p.adecuacionesCurriculares?.length?`<h2>Adecuaciones curriculares</h2><ul>${(Array.isArray(p.adecuacionesCurriculares)?p.adecuacionesCurriculares:[p.adecuacionesCurriculares]).map((x:any)=>"<li>"+esc(x)+"</li>").join("")}</ul>`:""}<h2>Evidencia</h2><p>${esc(p.evidencia)}</p></body></html>`;const w=window.open("","_blank");if(!w)return;w.document.write(html);w.document.close();w.focus();setTimeout(()=>w.print(),250)}
function RealPlanningGenerator(){const[data,setData]=useState<any>({courses:[],objectives:[],tpModules:[],plannings:[],aiReady:false});const[courseId,setCourseId]=useState("");const[subject,setSubject]=useState("");const[personalStage,setPersonalStage]=useState("");const[personalLevel,setPersonalLevel]=useState("");const[specialty,setSpecialty]=useState("");const[moduleId,setModuleId]=useState("");const[selected,setSelected]=useState<string[]>([]);const[duration,setDuration]=useState("90 minutos");const[modality,setModality]=useState("Clase a clase");const[instructions,setInstructions]=useState("");const[includeAdaptations,setIncludeAdaptations]=useState(false);const[adaptationContext,setAdaptationContext]=useState("");const[result,setResult]=useState<any>(null);const[implementationForm,setImplementationForm]=useState({implementedAt:new Date().toISOString().slice(0,10),evidence:"",notes:""});const[msg,setMsg]=useState("");const[loading,setLoading]=useState(false);
 const load=async()=>{const r=await fetch("/api/ai-planning");const d=await r.json();if(r.ok){setData(d);if(!courseId&&d.courses?.[0]){setCourseId(d.courses[0].id);setSubject(d.courses[0].teachingAssignments?.[0]?.subject||curricularSubjects(d.courses[0].level||"")?.[0]||"")}}else setMsg(d.error||"No fue posible cargar el generador")};useEffect(()=>{load()},[]);
 const individual=data.accountType==="INDIVIDUAL";const personalLevels=[...new Set((data.objectives||[]).map((x:any)=>x.level).filter(Boolean))] as string[];const personalStages=[...new Set(personalLevels.map(educationStage))];const choosePersonalLevel=async(level:string)=>{setPersonalLevel(level);setSubject("");setSelected([]);setResult(null);if(!level){setCourseId("");return}setMsg("Preparando curso personal...");const r=await fetch("/api/personal-course",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({level})});const x=await r.json();if(!r.ok){setMsg(x.error||"No fue posible seleccionar el curso");return}setCourseId(x.course.id);setData((d:any)=>({...d,courses:[...(d.courses||[]).filter((q:any)=>q.id!==x.course.id),x.course]}));setMsg("")};const course=data.courses?.find((x:any)=>x.id===courseId);const isTP=course?.track==="TP";const assignedSubjects=Array.from(new Set((course?.teachingAssignments||[]).map((x:any)=>x.subject))) as string[];const oaSubjects=[...new Set((data.objectives||[]).filter((x:any)=>x.level===course?.level).map((x:any)=>x.subject).filter(Boolean))] as string[];const availableSubjects=(individual?[...new Set([...oaSubjects,...curricularSubjects(course?.level||"")])]:assignedSubjects.length?assignedSubjects:curricularSubjects(course?.level||"")) as string[];const tpSpecialtiesAvailable=Array.from(new Set((data.tpModules||[]).filter((x:any)=>!course?.level||x.level===course.level).map((x:any)=>x.specialty))) as string[];const modules=(data.tpModules||[]).filter((x:any)=>x.specialty===specialty&&(!course?.level||x.level===course.level));const selectedModule=modules.find((x:any)=>x.id===moduleId);const objectives=isTP?(selectedModule?.objectives||[]).map((x:any)=>x.objective):(data.objectives||[]).filter((x:any)=>x.level===course?.level&&x.subject===subject);
 const changeCourse=(id:string)=>{setCourseId(id);const q=data.courses?.find((x:any)=>x.id===id);setSubject(q?.teachingAssignments?.[0]?.subject||"");setSelected([]);setSpecialty("");setModuleId("");setResult(null)};
 const generate=async()=>{if(!courseId||(!isTP&&!subject)||(isTP&&!moduleId)||!selected.length){setMsg(isTP?"Selecciona curso, especialidad, módulo y al menos un OA.":"Selecciona curso, asignatura y al menos un OA.");return}setLoading(true);setMsg("Generando planificación con IA...");setResult(null);const r=await fetch("/api/ai-planning",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({courseId,subject:isTP?(selectedModule?.name||subject):subject,moduleId:isTP?moduleId:undefined,objectiveIds:selected,duration,modality,instructions,includeAdaptations,adaptationContext})});const d=await r.json();setLoading(false);if(r.ok){setResult(d.planning);setMsg("✓ Planificación generada y guardada en PostgreSQL");load()}else setMsg(d.detail?d.error+": "+d.detail:d.error||"No fue posible generar")};
 const saveImplementation=async()=>{if(!result)return;const r=await fetch("/api/implementation",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({planningId:result.id,...implementationForm})});const d=await r.json();if(r.ok){setResult({...result,status:"IMPLEMENTED",implementation:d.record});setMsg("✓ Implementación registrada y Centro de Mando actualizado");load()}else setMsg(d.error||"No fue posible registrar la implementación")};const p=result?.content;return <div className="builder"><article className="panel form"><div className="step">1 · CONFIGURACIÓN CURRICULAR REAL</div><h2>Crear planificación con IA</h2><p>La IA utiliza el curso, la asignación docente y los OA almacenados en la plataforma.</p>{msg&&<div className={msg.startsWith("✓")?"success":"muted"}>{msg}</div>}<div className="formgrid">{individual?<><Field label="Nivel de enseñanza"><select value={personalStage} onChange={e=>{setPersonalStage(e.target.value);setPersonalLevel("");setCourseId("");setSubject("");setSelected([])}}><option value="">Seleccionar nivel</option>{personalStages.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Curso"><select value={personalLevel} onChange={e=>choosePersonalLevel(e.target.value)}><option value="">Seleccionar curso</option>{personalLevels.filter(x=>educationStage(x)===personalStage).map(x=><option key={x}>{x}</option>)}</select></Field></>:<Field label="Curso"><select value={courseId} onChange={e=>changeCourse(e.target.value)}><option value="">Seleccionar curso</option>{data.courses?.map((x:any)=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field>}<Field label="Asignatura"><select value={subject} onChange={e=>{setSubject(e.target.value);setSelected([])}}><option value="">Seleccionar asignatura</option>{availableSubjects.map(x=><option key={x}>{x}</option>)}</select></Field></div>{isTP&&<div className="formgrid"><Field label="Especialidad TP"><select value={specialty} onChange={e=>{setSpecialty(e.target.value);setModuleId("");setSelected([])}}><option value="">Seleccionar especialidad</option>{tpSpecialtiesAvailable.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Módulo oficial"><select value={moduleId} onChange={e=>{setModuleId(e.target.value);setSelected([])}}><option value="">Seleccionar módulo</option>{modules.map((m:any)=><option key={m.id} value={m.id}>{m.level} · {m.name}</option>)}</select></Field></div>}<Field label="Objetivos de Aprendizaje (OA)"><div className="oaList">{objectives.length?objectives.map((oa:any)=><div className="oa" key={oa.id}><b>{oa.code}</b><span>{oa.text}</span><input type="checkbox" checked={selected.includes(oa.id)} onChange={()=>setSelected(selected.includes(oa.id)?selected.filter(x=>x!==oa.id):[...selected,oa.id])}/></div>):<div className="oa"><span>No hay OA oficiales cargados para esta combinación. El piloto actual está habilitado para Matemática 8° Básico.</span></div>}</div>{objectives.length>0&&<small className="sourceTag">Fuente curricular almacenada: Currículum Nacional · MINEDUC</small>}</Field><div className="formgrid"><Field label="Duración"><select value={duration} onChange={e=>setDuration(e.target.value)}><option>45 minutos</option><option>90 minutos</option><option>135 minutos</option></select></Field><Field label="Modalidad"><select value={modality} onChange={e=>setModality(e.target.value)}><option>Clase a clase</option><option>Unidad</option><option>Mensual</option></select></Field></div><Field label="Indicaciones para la IA"><textarea value={instructions} onChange={e=>setInstructions(e.target.value)} placeholder="Ej.: incorporar trabajo colaborativo, DUA, recursos digitales y ticket de salida..."/></Field><div className="oa"><div><b>Adecuaciones curriculares (opcional)</b><span>Actívalas cuando la planificación requiera ajustes específicos, diferenciados del DUA general.</span></div><input type="checkbox" checked={includeAdaptations} onChange={e=>setIncludeAdaptations(e.target.checked)}/></div>{includeAdaptations&&<Field label="Necesidades y contexto para la adecuación"><textarea value={adaptationContext} onChange={e=>setAdaptationContext(e.target.value)} placeholder="Ej.: barreras de acceso, apoyos requeridos, ritmo de aprendizaje, formas alternativas de participación o evaluación. Evita ingresar diagnósticos o datos personales innecesarios."/></Field>}<button className="primary" disabled={loading||!data.aiReady||!selected.length} onClick={generate}>{loading?"Generando con IA...":"✦ Generar planificación con IA"}</button>{!data.aiReady&&<small className="sourceTag">OPENAI_API_KEY no disponible en el servidor.</small>}</article><article className="panel preview"><div className="step">2 · RESULTADO Y REGISTRO</div>{p?<><div className="success">✓ Guardada · vinculada a curso y OA</div><div className="actions noPrint"><button className="primary" onClick={()=>downloadPlanningPdf(result)}>Descargar PDF</button></div><h2>{result.title}</h2><div className="noPrint panel" style={{margin:"12px 0",padding:"14px"}}><b>Registrar implementación de la planificación</b><div className="formgrid"><Field label="Fecha de implementación"><input type="date" value={implementationForm.implementedAt} onChange={e=>setImplementationForm({...implementationForm,implementedAt:e.target.value})}/></Field><Field label="Evidencia"><input value={implementationForm.evidence} onChange={e=>setImplementationForm({...implementationForm,evidence:e.target.value})} placeholder="Ej.: guía aplicada, actividad realizada..."/></Field></div><Field label="Observaciones"><textarea value={implementationForm.notes} onChange={e=>setImplementationForm({...implementationForm,notes:e.target.value})}/></Field><button className="primary" onClick={saveImplementation}>{result.implementation?"Actualizar implementación":"Marcar como implementada"}</button>{result.implementation&&<small className="sourceTag">✓ Esta planificación ya registra implementación.</small>}</div><div className="doc"><b>Objetivo de clase</b><p>{renderValue(p.objetivoClase)}</p><h3>Indicadores</h3><p>{(p.indicadores||[]).join(" · ")}</p>{["inicio","desarrollo","cierre"].map(k=><div key={k}><h3>{k.charAt(0).toUpperCase()+k.slice(1)} · {p[k]?.minutos||""}</h3><p><b>Docente:</b> {renderValue(p[k]?.actividadesDocente)}</p><p><b>Estudiantes:</b> {renderValue(p[k]?.actividadesEstudiantes)}</p></div>)}<h3>Evaluación formativa</h3><p>{renderValue(p.evaluacionFormativa)}</p><h3>DUA</h3><p>{(p.dua||[]).join(" · ")}</p>{p.adecuacionesCurriculares&&<><h3>Adecuaciones curriculares</h3><p>{renderValue(p.adecuacionesCurriculares)}</p></>}<h3>Recursos y evidencia</h3><p>{(p.recursos||[]).join(" · ")} · {renderValue(p.evidencia)}</p></div></>:<div className="empty"><b>La planificación aparecerá aquí</b><p>Al generar, se guardará automáticamente como borrador y quedará vinculada a los OA seleccionados.</p></div>}</article></div>}
function TPDashboard(){const[selected,setSelected]=useState("Mecánica Industrial");const[action,setAction]=useState<null|{type:string,module:any}>(null);const mods=tpModules.filter(m=>m.specialty===selected);if(action)return <TPGenerator type={action.type} module={action.module} back={()=>setAction(null)}/>;return <><div className="tpHero"><div><small>FORMACIÓN DIFERENCIADA TÉCNICO-PROFESIONAL</small><h2>Gestión curricular TP</h2><p>Especialidad → Módulo → OA → Planificación → Evaluación → Cobertura.</p></div><div className="tpStat"><b>{tpSpecialties.length}</b><span>Especialidades oficiales</span></div></div><article className="panel tpSelector"><div><small>ESPECIALIDAD</small><select value={selected} onChange={e=>setSelected(e.target.value)}>{tpSpecialties.map(x=><option key={x}>{x}</option>)}</select></div><div><small>ESTADO CURRICULAR</small><b>{mods.length?mods.length+" módulos verificados":"Módulos oficiales pendientes de carga"}</b></div></article>{mods.length>0?<article className="panel tpBlock"><div className="panelHead"><div><small>MÓDULOS OFICIALES</small><h2>{selected}</h2></div><span className="verified">✓ Currículum Nacional</span></div><div className="moduleGrid">{mods.map(m=><div className="moduleCard" key={m.id}><div><b>{m.code}</b><span>{m.level}</span></div><h3>{m.name}</h3>{m.mention&&<p>{m.mention}</p>}<small>{m.oa.length?m.oa.join(" · "):"OA por completar desde programa oficial"}</small><div className="moduleActions"><button onClick={()=>setAction({type:"planificación",module:m})}>Crear planificación</button><button onClick={()=>setAction({type:"evaluación",module:m})}>Crear evaluación</button></div></div>)}</div></article>:<article className="panel emptyTp"><b>Especialidad incorporada al catálogo nacional</b><p>Sus módulos se habilitarán cuando finalice la carga y verificación del programa oficial MINEDUC.</p></article>}<article className="panel tpCatalog"><div className="panelHead"><div><small>CATÁLOGO NACIONAL</small><h2>35 especialidades · 15 sectores</h2></div></div>{tpSectors.map(sector=><div className="sectorRow" key={sector}><b>{sector}</b><span>{tpCatalog.filter(x=>x.sector===sector).map(x=>x.specialty).join(" · ")}</span></div>)}</article></>}

function AdminPanel({currentUser}:{currentUser:any}){const[view,setView]=useState("colegios");const[syncing,setSyncing]=useState(false);const[syncResult,setSyncResult]=useState("");const[editingUser,setEditingUser]=useState<any>(null);const[editingSchool,setEditingSchool]=useState<any>(null);const[data,setData]=useState<any[]>([]);const[msg,setMsg]=useState("");const[school,setSchool]=useState({name:"",rbd:"",commune:"",region:"Antofagasta",organizationId:""});const[user,setUser]=useState({name:"",email:"",password:"",role:"DIRECTOR",organizationId:"",schoolId:""});const load=async()=>{try{const r=await fetch("/api/admin");if(r.ok){const d=await r.json();setData(d);if(d[0]){setSchool(s=>({...s,organizationId:s.organizationId||d[0].id}));setUser(u=>({...u,organizationId:u.organizationId||d[0].id}))}}}catch{}};useEffect(()=>{load()},[]);const patch=async(body:any)=>{setMsg("Actualizando...");const r=await fetch("/api/admin",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();setMsg(r.ok?"✓ Actualizado correctamente":d.error||"Error al actualizar");if(r.ok)load()};const remove=async(body:any)=>{if(!confirm(body.kind==="course"?"¿Quitar este curso?":"¿Quitar esta asignación docente?"))return;setMsg("Actualizando...");const r=await fetch("/api/academic",{method:"DELETE",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();setMsg(r.ok?"✓ Actualizado correctamente":d.error||"Error");if(r.ok)load()};const update=async(body:any)=>{setMsg("Actualizando...");const r=await fetch("/api/academic",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();setMsg(r.ok?"✓ Curso actualizado":d.error||"Error");if(r.ok)load()};const save=async(body:any)=>{setMsg("Guardando...");const r=await fetch("/api/admin",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();setMsg(r.ok?"✓ Guardado correctamente":d.error||"Error al guardar");if(r.ok)load()};const schools=data.flatMap((o:any)=>o.schools||[]);const users=data.flatMap((o:any)=>o.users||[]);return <><div className="tpHero"><div><small>ADMINISTRACIÓN CENTRAL</small><h2>Organizaciones, colegios y usuarios</h2><p>Superadministrador → Sostenedor → Colegio → Usuarios.</p></div><div className="tpStat"><b>{schools.length}</b><span>Colegios registrados</span></div></div><div className="adminTabs"><button className={view==="colegios"?"active":""} onClick={()=>setView("colegios")}>Colegios</button><button className={view==="usuarios"?"active":""} onClick={()=>setView("usuarios")}>Usuarios</button><button className={view==="estructura"?"active":""} onClick={()=>setView("estructura")}>Estructura</button><button className={view==="roles"?"active":""} onClick={()=>setView("roles")}>Roles y permisos</button>{currentUser?.role==="SUPERADMIN"&&<button className={view==="curriculum"?"active":""} onClick={()=>setView("curriculum")}>Currículum oficial</button>}</div>{msg&&<div className="success">{msg}</div>}{view==="colegios"&&<div className="builder"><article className="panel form"><div className="step">NUEVO ESTABLECIMIENTO</div><h2>Crear colegio</h2>{data.length===0?<><p className="muted">Primero crea el sostenedor u organización.</p><Field label="Nombre del sostenedor"><input id="orgName" placeholder="Corporación, DAEM, SLEP..."/></Field><button className="primary" onClick={()=>{const el=document.getElementById("orgName") as HTMLInputElement;save({kind:"organization",name:el?.value})}}>Crear sostenedor</button></>:<><Field label="Nombre"><input value={school.name} onChange={e=>setSchool({...school,name:e.target.value})}/></Field><div className="formgrid"><Field label="RBD"><input value={school.rbd} onChange={e=>setSchool({...school,rbd:e.target.value})}/></Field><Field label="Comuna"><input value={school.commune} onChange={e=>setSchool({...school,commune:e.target.value})}/></Field></div><div className="formgrid"><Field label="Región"><select value={school.region} onChange={e=>setSchool({...school,region:e.target.value})}>{["Arica y Parinacota","Tarapacá","Antofagasta","Atacama","Coquimbo","Valparaíso","Metropolitana","O'Higgins","Maule","Ñuble","Biobío","La Araucanía","Los Ríos","Los Lagos","Aysén","Magallanes"].map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Sostenedor"><select value={school.organizationId} onChange={e=>setSchool({...school,organizationId:e.target.value})}>{data.map((o:any)=><option value={o.id} key={o.id}>{o.name}</option>)}</select></Field></div><button className="primary" onClick={()=>save({kind:"school",...school})}>Crear establecimiento</button></>}</article><article className="panel preview"><div className="step">ESTABLECIMIENTOS</div><h2>Administración de colegios</h2>{editingSchool&&<div className="adminEdit"><Field label="Nombre"><input value={editingSchool.name} onChange={e=>setEditingSchool({...editingSchool,name:e.target.value})}/></Field><div className="formgrid"><Field label="RBD"><input value={editingSchool.rbd||""} onChange={e=>setEditingSchool({...editingSchool,rbd:e.target.value})}/></Field><Field label="Comuna"><input value={editingSchool.commune||""} onChange={e=>setEditingSchool({...editingSchool,commune:e.target.value})}/></Field></div><div className="actions"><button onClick={()=>setEditingSchool(null)}>Cancelar</button><button className="primary" onClick={async()=>{await patch({kind:"school",id:editingSchool.id,name:editingSchool.name,rbd:editingSchool.rbd,commune:editingSchool.commune,region:editingSchool.region});setEditingSchool(null)}}>Guardar cambios</button></div></div>}{schools.length?schools.map((s:any)=><div className="adminRow" key={s.id}><div><b>{s.name}</b><span>{s.rbd||"Sin RBD"} · {s.commune||"Sin comuna"} · {s.region||"Sin región"}</span></div><div><span className="verified">{s.active?"Activo":"Inactivo"}</span><button onClick={()=>setEditingSchool({...s})}>Editar</button><button onClick={()=>patch({kind:"school",id:s.id,active:!s.active})}>{s.active?"Desactivar":"Activar"}</button></div></div>):<p className="muted">Aún no existen establecimientos.</p>}</article></div>}{view==="usuarios"&&<div className="builder"><article className="panel form"><div className="step">NUEVO USUARIO</div><h2>Crear usuario</h2><Field label="Nombre"><input value={user.name} onChange={e=>setUser({...user,name:e.target.value})}/></Field><Field label="Correo electrónico"><input type="email" value={user.email} onChange={e=>setUser({...user,email:e.target.value})}/></Field><Field label="Contraseña inicial"><input type="password" minLength={12} value={user.password} onChange={e=>setUser({...user,password:e.target.value})} placeholder="Mínimo 12 caracteres"/></Field><div className="formgrid"><Field label="Rol"><select value={user.role} onChange={e=>setUser({...user,role:e.target.value})}><option value="SOSTENEDOR">Sostenedor</option><option value="DIRECTOR">Director</option><option value="UTP">Jefe UTP</option><option value="DOCENTE">Docente</option></select></Field><Field label="Establecimiento"><select value={user.schoolId} onChange={e=>setUser({...user,schoolId:e.target.value})}><option value="">Acceso sostenedor / general</option>{schools.map((s:any)=><option value={s.id} key={s.id}>{s.name}</option>)}</select></Field></div><Field label="Sostenedor"><select value={user.organizationId} onChange={e=>setUser({...user,organizationId:e.target.value})}>{data.map((o:any)=><option value={o.id} key={o.id}>{o.name}</option>)}</select></Field><button className="primary" disabled={!data.length} onClick={()=>save({kind:"user",...user})}>Crear usuario</button></article><article className="panel preview"><div className="step">USUARIOS REGISTRADOS</div><h2>Control de acceso</h2>{editingUser&&<div className="adminEdit"><Field label="Nombre"><input value={editingUser.name} onChange={e=>setEditingUser({...editingUser,name:e.target.value})}/></Field><Field label="Nueva contraseña (opcional)"><input type="password" minLength={12} value={editingUser.password} onChange={e=>setEditingUser({...editingUser,password:e.target.value})} placeholder="Mínimo 12 caracteres"/></Field><div className="actions"><button onClick={()=>setEditingUser(null)}>Cancelar</button><button className="primary" onClick={async()=>{await patch({kind:"user",id:editingUser.id,name:editingUser.name,...(editingUser.password?{password:editingUser.password}:{})});setEditingUser(null)}}>Guardar cambios</button></div></div>}{users.length?users.map((u:any)=><div className="adminRow" key={u.id}><div><b>{u.name}</b><span>{u.role} · {u.email}</span></div><div><span className="verified">{u.active?"Activo":"Inactivo"}</span>{u.role!=="SUPERADMIN"&&<><button onClick={()=>setEditingUser({id:u.id,name:u.name,password:""})}>Editar</button><button onClick={()=>patch({kind:"user",id:u.id,active:!u.active})}>{u.active?"Desactivar":"Activar"}</button></>}</div></div>):<p className="muted">Aún no existen usuarios.</p>}</article></div>}{view==="estructura"&&<article className="panel"><div className="panelHead"><div><small>ESTRUCTURA INSTITUCIONAL</small><h2>Sostenedores, establecimientos y usuarios</h2></div></div>{data.map((o:any)=><div className="orgTree" key={o.id}><h3>{o.name}</h3><p>{o.schools?.length||0} establecimientos · {o.users?.length||0} usuarios</p>{(o.schools||[]).map((s:any)=><div className="schoolTree" key={s.id}><b>{s.name}</b><span>{s.rbd?"RBD "+s.rbd:"Sin RBD"} · {s.commune||"Sin comuna"}</span><div>{(o.users||[]).filter((u:any)=>u.schoolId===s.id).map((u:any)=><small key={u.id}>{roleLabel(u.role)} · {u.name}</small>)}</div></div>)}</div>)}</article>}{view==="curriculum"&&currentUser?.role==="SUPERADMIN"&&<article className="panel"><div className="panelHead"><div><small>CATÁLOGO OFICIAL MINEDUC</small><h2>Sincronización curricular</h2><p>Importa el catálogo oficial versionado sin duplicar módulos ni relaciones OA existentes.</p></div></div><div className="moduleCard"><h3>Electricidad · 3° y 4° Medio TP</h3><p>8 módulos oficiales con relaciones a Objetivos de Aprendizaje verificadas.</p><button className="primary" disabled={syncing} onClick={async()=>{if(!confirm("¿Sincronizar el catálogo oficial de Electricidad con la base de datos?"))return;setSyncing(true);setSyncResult("Sincronizando...");try{const r=await fetch("/api/admin/sync-electricidad",{method:"POST"});const d=await r.json();setSyncResult(r.ok?`✓ Sincronización completada: ${d.modules} módulos · ${d.objectiveLinks} relaciones OA`:d.error||"No fue posible sincronizar")}catch{setSyncResult("No fue posible sincronizar")}finally{setSyncing(false)}}}>{syncing?"Sincronizando...":"Sincronizar Electricidad"}</button>{syncResult&&<p className={syncResult.startsWith("✓")?"success":"muted"}>{syncResult}</p>}</div><div className="moduleCard"><h3>Mecánica Industrial · 3° y 4° Medio TP</h3><p>Incluye módulos comunes de 3° Medio y las menciones Mantenimiento Electromecánico, Máquinas-Herramientas y Matricería en 4° Medio.</p><button className="primary" disabled={syncing} onClick={async()=>{if(!confirm("¿Sincronizar el catálogo oficial de Mecánica Industrial con la base de datos?"))return;setSyncing(true);setSyncResult("Sincronizando Mecánica Industrial...");try{const r=await fetch("/api/admin/sync-mecanica-industrial",{method:"POST"});const d=await r.json();setSyncResult(r.ok?`✓ Mecánica Industrial sincronizada: ${d.modules} módulos · ${d.objectiveLinks} relaciones OA`:d.error||"No fue posible sincronizar")}catch{setSyncResult("No fue posible sincronizar")}finally{setSyncing(false)}}}>{syncing?"Sincronizando...":"Sincronizar Mecánica Industrial"}</button></div></article>}{view==="roles"&&<article className="panel"><div className="panelHead"><div><small>PERMISOS</small><h2>Acceso según perfil</h2></div></div><div className="roleGrid">{[["Superadministrador","Gestiona sostenedores, colegios y usuarios"],["Sostenedor","Administra sus establecimientos"],["Director","Centro de Mando y gestión institucional"],["Jefe UTP","Currículum, cobertura, planificación y evaluación"],["Docente","Planifica, evalúa y registra implementación"]].map(x=><div className="moduleCard" key={x[0]}><h3>{x[0]}</h3><p>{x[1]}</p></div>)}</div></article>}</>}

function TPGenerator({type,module,back}:{type:string,module:any,back:()=>void}){const[done,setDone]=useState(false);const evaluation=type==="evaluación";return <div className="builder"><article className="panel form"><button className="backBtn" onClick={back}>← Volver a Cobertura TP</button><div className="step">TP · CONFIGURACIÓN CURRICULAR</div><h2>Crear {type} TP con IA</h2><div className="tpContext"><b>{module.specialty}</b><span>{module.level}{module.mention?" · "+module.mention:""}</span><strong>{module.code} · {module.name}</strong></div><Field label="Objetivos de Aprendizaje"><div className="oaList">{module.oa.length?module.oa.map((oa:string)=><div className="oa" key={oa}><b>{oa}</b><span>Objetivo oficial asociado al módulo</span><input type="checkbox" defaultChecked/></div>):<div className="oa"><span>OA pendiente de completar desde el programa oficial MINEDUC.</span></div>}</div></Field>{evaluation?<div className="formgrid"><Field label="Tipo"><select><option>Formativa</option><option>Sumativa</option><option>Diagnóstica</option></select></Field><Field label="Instrumento"><select><option>Rúbrica de desempeño</option><option>Lista de cotejo</option><option>Prueba mixta</option></select></Field></div>:<div className="formgrid"><Field label="Duración"><select><option>2 horas pedagógicas</option><option>4 horas pedagógicas</option><option>Unidad completa</option></select></Field><Field label="Modalidad"><select><option>Taller práctico</option><option>Teórico-práctica</option><option>Dual / Alternancia</option></select></Field></div>}<Field label="Indicaciones para la IA"><textarea placeholder="Contexto, recursos del taller, seguridad, metodología o adecuaciones..."/></Field><button className="primary" disabled={!module.oa.length} onClick={()=>setDone(true)}>✦ Generar {type} TP con IA</button>{!module.oa.length&&<small className="sourceTag">La generación se habilitará cuando los OA oficiales del módulo estén cargados.</small>}</article><article className="panel preview"><div className="step">RESULTADO TP</div>{done?<><div className="success">✓ Borrador vinculado al módulo y OA</div><h2>{module.name}</h2><div className="doc"><b>{module.specialty} · {module.code}</b><p>{evaluation?"Instrumento alineado al desempeño técnico, OA del módulo, criterios de evaluación y seguridad.":"Planificación técnico-práctica alineada al módulo, OA, desempeño esperado, seguridad y evidencia de aprendizaje."}</p></div><div className="actions"><button>Editar</button><button>Guardar</button><button>Exportar</button></div></>:<div className="empty"><b>Tu {type} TP aparecerá aquí</b><p>Conservará la trazabilidad Especialidad → Módulo → OA → Evidencia.</p></div>}</article></div>}
function HCOfferingsPanel(){const[level,setLevel]=useState("3° Medio");const[data,setData]=useState<any>({offerings:[],courses:[],teachers:[]});const[msg,setMsg]=useState("");const[selected,setSelected]=useState(hcDifferentiatedCatalog[0]?.name||"");const[custom,setCustom]=useState("");const[pick,setPick]=useState<Record<string,{courseId:string,teacherId:string}>>({});const load=async()=>{const r=await fetch("/api/hc-offerings?year=2027&level="+encodeURIComponent(level));if(r.ok)setData(await r.json())};useEffect(()=>{load()},[level]);const add=async(body:any)=>{const r=await fetch("/api/hc-offerings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...body,year:2027,level})});const d=await r.json();setMsg(r.ok?"✓ Oferta curricular agregada":d.error||"No fue posible guardar");if(r.ok){setCustom("");load()}};const remove=async(id:string,kind="offering")=>{const r=await fetch("/api/hc-offerings",{method:"DELETE",headers:{"Content-Type":"application/json"},body:JSON.stringify(kind==="assignment"?{kind,id}:{id})});if(r.ok)load()};const assign=async(offeringId:string)=>{const p=pick[offeringId]||{} as any;if(!p.courseId||!p.teacherId){setMsg("Selecciona curso y docente");return}const r=await fetch("/api/hc-offerings",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({kind:"assignment",offeringId,...p})});const d=await r.json();setMsg(r.ok?"✓ Docente asignado a la oferta HC":d.error||"No fue posible asignar");if(r.ok)load()};const official=hcDifferentiatedCatalog.find(x=>x.name===selected);return <article className="panel hcOfferings"><div className="panelHead"><div><small>FORMACIÓN DIFERENCIADA HC</small><h2>Oferta HC 3° y 4° Medio</h2><p>UTP define la oferta del establecimiento y la vincula con cursos y docentes.</p></div><select value={level} onChange={e=>setLevel(e.target.value)}><option>3° Medio</option><option>4° Medio</option></select></div>{msg&&<div className="success">{msg}</div>}<div className="builder"><div className="form"><Field label="Catálogo oficial MINEDUC"><select value={selected} onChange={e=>setSelected(e.target.value)}>{hcDifferentiatedCatalog.map(x=><option key={x.name}>{x.name}</option>)}</select></Field><p className="muted">{official?.area} · {official?.weeklyHours} horas semanales · MINEDUC</p><button className="primary" onClick={()=>official&&add({name:official.name,source:"MINEDUC"})}>Agregar a la oferta</button></div><div className="form"><Field label="Opción institucional"><input value={custom} onChange={e=>setCustom(e.target.value)} placeholder="Nombre de la opción institucional"/></Field><p className="muted">Se identificará como Institucional, separada del catálogo oficial.</p><button disabled={!custom.trim()} onClick={()=>add({name:custom,source:"INSTITUTIONAL"})}>Crear opción institucional</button></div></div><div className="hcOfferList">{data.offerings?.length?data.offerings.map((x:any)=>{const p=pick[x.id]||{courseId:"",teacherId:""};return <div className="hcOfferCard" key={x.id}><div className="adminRow"><div><b>{x.name}</b><span>{x.area||"Oferta propia"} · {x.weeklyHours?x.weeklyHours+" h/sem":"Horas por definir"}</span></div><div><span className="verified">{x.source==="MINEDUC"?"MINEDUC":"Institucional"}</span><button onClick={()=>remove(x.id)}>Quitar</button></div></div><div className="hcAssign"><select value={p.courseId} onChange={e=>setPick({...pick,[x.id]:{...p,courseId:e.target.value}})}><option value="">Seleccionar curso HC</option>{data.courses?.map((q:any)=><option key={q.id} value={q.id}>{q.name}</option>)}</select><select value={p.teacherId} onChange={e=>setPick({...pick,[x.id]:{...p,teacherId:e.target.value}})}><option value="">Seleccionar docente</option>{data.teachers?.map((t:any)=><option key={t.id} value={t.id}>{t.name}</option>)}</select><button onClick={()=>assign(x.id)}>Asignar</button></div>{x.teachingAssignments?.map((a:any)=><small className="assignmentLine" key={a.id}>{a.course.name} · {a.teacher.name} <button onClick={()=>remove(a.id,"assignment")}>Quitar</button></small>)}</div>}):<p className="muted">Aún no se ha configurado oferta para {level}.</p>}</div></article>}
function AcademicPanel(){
 const[data,setData]=useState<any>({courses:[],teachers:[]});const[msg,setMsg]=useState("");const[jec,setJec]=useState<boolean|null>(null);const[level,setLevel]=useState("1° Básico");const[track,setTrack]=useState("BASICA");const[selectedLetters,setSelectedLetters]=useState<string[]>(["A"]);const[assignment,setAssignment]=useState({courseId:"",subject:"Matemática",teacherId:""});
 const letters="ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");const levels=["Prekínder","Kínder","1° Básico","2° Básico","3° Básico","4° Básico","5° Básico","6° Básico","7° Básico","8° Básico","1° Medio","2° Medio","3° Medio","4° Medio"];
 const inferTrack=(x:string)=>x==="Prekínder"||x==="Kínder"?"PARVULARIA":x.includes("Básico")?"BASICA":"HC";
 const load=async()=>{const r=await fetch("/api/academic?year=2027");if(r.ok){const d=await r.json();setData(d);setJec(d.academicYear?.jec??null);if(d.courses?.[0])setAssignment((x:any)=>({...x,courseId:x.courseId||d.courses[0].id}));if(d.teachers?.[0])setAssignment((x:any)=>({...x,teacherId:x.teacherId||d.teachers[0].id}))}};
 useEffect(()=>{load()},[]);
 const remove=async(body:any)=>{if(!confirm(body.kind==="course"?"¿Quitar este curso?":"¿Quitar esta asignación docente?"))return;setMsg("Actualizando...");const r=await fetch("/api/academic",{method:"DELETE",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();setMsg(r.ok?"✓ Actualizado correctamente":d.error||"Error");if(r.ok)load()};const update=async(body:any)=>{setMsg("Actualizando...");const r=await fetch("/api/academic",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();setMsg(r.ok?"✓ Curso actualizado":d.error||"Error");if(r.ok)load()};const save=async(body:any)=>{setMsg("Guardando...");const r=await fetch("/api/academic",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...body,year:2027})});const d=await r.json();setMsg(r.ok?"✓ Guardado correctamente":d.error||"Error");if(r.ok)load();return r.ok};
 const createCourses=async()=>{if(!selectedLetters.length){setMsg("Selecciona al menos un paralelo");return}setMsg("Creando cursos...");let ok=0;for(const letter of selectedLetters){if(await save({kind:"course",name:`${level} ${letter}`,level,track}))ok++}setMsg(`✓ ${ok} curso(s) procesados para ${level}`)};
 const changeLevel=(v:string)=>{setLevel(v);setTrack(inferTrack(v))};
 const saveJec=async(v:boolean)=>{setJec(v);const r=await fetch("/api/academic",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({year:2027,jec:v})});setMsg(r.ok?"✓ Régimen de jornada guardado":"No fue posible guardar el régimen")};
 return <><div className="tpHero"><div><small>CONFIGURACIÓN ACADÉMICA</small><h2>Cursos y Asignaturas</h2><p>El Director define los niveles y paralelos que existen realmente en su establecimiento.</p></div><div className="tpStat"><b>{data.courses?.length||0}</b><span>Cursos 2027</span></div></div>{msg&&<div className="success">{msg}</div>}<article className="panel jecPanel"><div><small>RÉGIMEN DE JORNADA</small><h2>Plan de estudios del establecimiento</h2><p>Seleccione la modalidad que corresponde al establecimiento para este año académico.</p></div><div className="jecChoices"><button className={jec===true?"active":""} onClick={()=>saveJec(true)}>Con JEC</button><button className={jec===false?"active":""} onClick={()=>saveJec(false)}>Sin JEC</button></div></article><div className="builder"><article className="panel form"><div className="step">CONFIGURAR CURSOS</div><h2>Nivel y paralelos A–Z</h2><Field label="Nivel"><select value={level} onChange={e=>changeLevel(e.target.value)}>{levels.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Modalidad"><select value={track} onChange={e=>setTrack(e.target.value)}><option value="PARVULARIA">Parvularia</option><option value="BASICA">Básica</option><option value="HC">Media HC</option><option value="TP">Media TP</option></select></Field><Field label="Paralelos que existen en el establecimiento"><div className="letterGrid">{letters.map(letter=><button type="button" key={letter} className={selectedLetters.includes(letter)?"active":""} onClick={()=>setSelectedLetters(selectedLetters.includes(letter)?selectedLetters.filter(x=>x!==letter):[...selectedLetters,letter].sort())}>{letter}</button>)}</div></Field><p className="muted">Se crearán: {selectedLetters.length?selectedLetters.map(x=>level+" "+x).join(" · "):"ningún curso seleccionado"}</p><button className="primary" onClick={createCourses}>Crear cursos seleccionados</button></article><article className="panel form"><div className="step">ASIGNACIÓN DOCENTE</div><h2>Asignar asignatura</h2><Field label="Curso"><select value={assignment.courseId} onChange={e=>setAssignment({...assignment,courseId:e.target.value})}>{data.courses?.map((x:any)=><option value={x.id} key={x.id}>{x.name}</option>)}</select></Field><Field label="Asignatura"><select value={assignment.subject} onChange={e=>setAssignment({...assignment,subject:e.target.value})}>{(curricularSubjects(data.courses?.find((x:any)=>x.id===assignment.courseId)?.level)||[]).map(x=><option key={x}>{x}</option>)}<option value="__custom">+ Agregar asignatura institucional</option></select></Field>{assignment.subject==="__custom"&&<Field label="Asignatura institucional"><input placeholder="Nombre de la asignatura" onChange={e=>setAssignment({...assignment,subject:e.target.value})}/></Field>}<Field label="Docente"><select value={assignment.teacherId} onChange={e=>setAssignment({...assignment,teacherId:e.target.value})}>{data.teachers?.map((x:any)=><option value={x.id} key={x.id}>{x.name}</option>)}</select></Field><button className="primary" disabled={!data.courses?.length||!data.teachers?.length} onClick={()=>save({kind:"assignment",...assignment})}>Asignar docente</button></article></div><article className="panel"><div className="panelHead"><div><small>ESTRUCTURA 2027</small><h2>Cursos configurados por el establecimiento</h2></div></div>{data.courses?.length?data.courses.map((x:any)=><div className="adminRow" key={x.id}><div><b>{x.name}</b><span>{x.level} · {x.track}</span>{x.teachingAssignments?.map((a:any)=><small className="assignmentLine" key={a.id}>{a.subject} · {a.teacher.name} <button onClick={()=>remove({kind:"assignment",id:a.id})}>Quitar</button></small>)}</div><div className="courseActions"><select value={x.track} onChange={e=>update({kind:"course",id:x.id,track:e.target.value})}><option value="PARVULARIA">Parvularia</option><option value="BASICA">Básica</option><option value="HC">Media HC</option><option value="TP">Media TP</option></select><span className="verified">{x.teachingAssignments?.length||0} asignaciones</span><button onClick={()=>remove({kind:"course",id:x.id})}>Quitar curso</button></div></div>):<p className="muted">El Director aún no ha configurado los cursos de este establecimiento.</p>}</article><HCOfferingsPanel/></>
}

function downloadSupportMaterial(result:any){if(!result)return;const p=result.content||{};const esc=(s:any)=>String(s??"").replace(/[&<>"]/g,(m)=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"} as any)[m]);const render=(v:any)=>esc(renderValue(v));const sections=(p.secciones||[]).map((s:any,n:number)=>`<section><h2>${render(s.titulo||"Sección "+(n+1))}</h2><div>${render(s.contenido)}</div>${s.apoyoVisual?`<div class="visual"><b>Apoyo visual:</b> ${render(s.apoyoVisual)}</div>`:""}</section>`).join("");const images=(p.ilustraciones||[]).map((x:any)=>x?.image?`<figure><img src="${esc(x.image)}"><figcaption>${render(x.descripcion)}</figcaption></figure>`:"").join("");const html=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(result.title)}</title><style>@page{size:A4;margin:15mm}body{font-family:Arial,sans-serif;color:#172033;font-size:11pt;line-height:1.45}h1{font-size:21pt;color:#123f6d;margin:0 0 5mm}h2{font-size:14pt;color:#123f6d;border-bottom:2px solid #e5eaf1;padding-bottom:2mm;margin-top:7mm}.meta{border:1px solid #d7e1ec;border-top:4px solid #2563eb;padding:4mm;border-radius:3mm;margin-bottom:6mm}.visual{background:#f5f8fc;padding:3mm;margin-top:3mm;border-radius:2mm}.images{display:grid;grid-template-columns:1fr 1fr;gap:5mm}figure{margin:0;break-inside:avoid;border:1px solid #d7e1ec;padding:3mm;border-radius:3mm}img{display:block;width:100%;max-height:90mm;object-fit:contain}figcaption{font-size:9pt;color:#60758b;margin-top:2mm}section{break-inside:avoid}ul{padding-left:6mm}</style></head><body><h1>${esc(result.title)}</h1><div class="meta"><b>Tipo:</b> ${esc(result.materialType||"Material de apoyo")}<br><b>Curso:</b> ${esc(result.course?.name||"")}${p.proposito?`<br><b>Propósito:</b> ${render(p.proposito)}`:""}</div>${p.instrucciones?`<p>${render(p.instrucciones)}</p>`:""}${sections}${images?`<h2>Ilustraciones didácticas</h2><div class="images">${images}</div>`:""}${p.cierre?`<h2>Cierre</h2><p>${render(p.cierre)}</p>`:""}</body></html>`;const w=window.open("","_blank");if(!w)return;w.document.write(html);w.document.close();const imgs=Array.from(w.document.images);Promise.all(imgs.map((img:any)=>img.complete?Promise.resolve():new Promise<void>(resolve=>{img.onload=()=>resolve();img.onerror=()=>resolve()}))).then(()=>{w.focus();setTimeout(()=>w.print(),150)})}
function SupportMaterials(){const types=["Presentación","Guía de apoyo","Mapa conceptual","Mapa mental","Guía de aprendizaje","Afiche","Tríptico","Díptico","Otro material educativo"];const[type,setType]=useState(types[0]);const[topic,setTopic]=useState("");const[objectiveId,setObjectiveId]=useState("");const[courseId,setCourseId]=useState("");const[subject,setSubject]=useState("");const[includeImages,setIncludeImages]=useState(true);const[personalStage,setPersonalStage]=useState("");const[personalLevel,setPersonalLevel]=useState("");const[data,setData]=useState<any>({courses:[],materials:[],usage:{}});const[result,setResult]=useState<any>(null);const[msg,setMsg]=useState("");const[loading,setLoading]=useState(false);const load=()=>{fetch("/api/ai-planning").then(r=>r.json()).then(x=>setData((d:any)=>({...d,courses:x.courses||[],objectives:x.objectives||[],accountType:x.accountType}))).catch(()=>{});fetch("/api/ai-material").then(r=>r.json()).then(x=>setData((d:any)=>({...d,materials:x.materials||[],usage:x.usage||{}}))).catch(()=>{})};useEffect(()=>{load()},[]);const individual=data.accountType==="INDIVIDUAL";const personalLevels=[...new Set((data.objectives||[]).map((x:any)=>x.level).filter(Boolean))] as string[];const personalStages=[...new Set(personalLevels.map(educationStage))];const choosePersonalLevel=async(level:string)=>{setPersonalLevel(level);setSubject("");setObjectiveId("");setResult(null);if(!level){setCourseId("");return}setMsg("Preparando curso personal...");const r=await fetch("/api/personal-course",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({level})});const x=await r.json();if(!r.ok){setMsg(x.error||"No fue posible seleccionar el curso");return}setCourseId(x.course.id);setData((d:any)=>({...d,courses:[...(d.courses||[]).filter((q:any)=>q.id!==x.course.id),x.course]}));setMsg("")};const course=data.courses.find((x:any)=>x.id===courseId);const assignedMaterialSubjects=[...new Set((course?.teachingAssignments||[]).map((x:any)=>x.subject).filter(Boolean))] as string[];const oaMaterialSubjects=[...new Set((data.objectives||[]).filter((x:any)=>x.level===course?.level).map((x:any)=>x.subject).filter(Boolean))] as string[];const catalogMaterialSubjects=curricularSubjects(course?.level||"") as string[];const subjects=[...new Set([...assignedMaterialSubjects,...oaMaterialSubjects,...catalogMaterialSubjects])].filter(Boolean).sort((a,b)=>a.localeCompare(b,"es")) as string[];const generate=async()=>{if(!courseId||!topic){setMsg("Selecciona un curso e indica el tema.");return}setLoading(true);setMsg("");const r=await fetch("/api/ai-material",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({materialType:type,courseId,subject,topic,objectiveId,includeImages})});const x=await r.json();setLoading(false);if(!r.ok){setMsg([x.error,x.detail].filter(Boolean).join(" · ")||"No fue posible generar el material");return}setResult(x.material);setMsg("✓ Material creado y guardado");load()};const p=result?.content||{};return <article className="panel"><div className="tpHero"><div><small>CREACIÓN CON IA</small><h2>Material de apoyo</h2><p>Presentaciones, guías, mapas, afiches, trípticos, dípticos y otros recursos educativos.</p></div>{data.usage?.limit&&<div><b>{data.usage.used||0}/{data.usage.limit}</b><small> generaciones IA utilizadas</small></div>}</div><div className="formGrid"><Field label="Tipo de material"><select value={type} onChange={e=>setType(e.target.value)}>{types.map(x=><option key={x}>{x}</option>)}</select></Field>{individual?<><Field label="Nivel de enseñanza"><select value={personalStage} onChange={e=>{setPersonalStage(e.target.value);setPersonalLevel("");setCourseId("");setSubject("");setObjectiveId("")}}><option value="">Seleccionar nivel…</option>{personalStages.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Curso"><select value={personalLevel} onChange={e=>choosePersonalLevel(e.target.value)}><option value="">Seleccionar curso…</option>{personalLevels.filter(x=>educationStage(x)===personalStage).map(x=><option key={x}>{x}</option>)}</select></Field></>:<Field label="Curso"><select value={courseId} onChange={e=>{setCourseId(e.target.value);setSubject("");setObjectiveId("")}}><option value="">Seleccionar…</option>{data.courses.map((x:any)=><option value={x.id} key={x.id}>{x.name}</option>)}</select></Field>}<Field label="Asignatura"><select value={subject} onChange={e=>{setSubject(e.target.value);setObjectiveId("")}}><option value="">Seleccionar…</option>{subjects.map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Tema o contenido"><input value={topic} onChange={e=>setTopic(e.target.value)} placeholder="Contenido a trabajar"/></Field><Field label="OA asociado"><select value={objectiveId} onChange={e=>setObjectiveId(e.target.value)}><option value="">Sin OA asociado</option>{(data.objectives||[]).filter((x:any)=>x.level===course?.level&&x.subject===subject).map((x:any)=><option value={x.id} key={x.id}>{x.code} · {x.text}</option>)}</select></Field></div><label className="imageToggle"><input type="checkbox" checked={includeImages} onChange={e=>setIncludeImages(e.target.checked)}/><span>Incluir ilustraciones generadas por IA</span></label><button className="primary" onClick={generate} disabled={loading}>{loading?"Creando material e ilustraciones…":"Crear con IA"}</button>{msg&&<div className="callout">{msg}</div>}{result&&<div className="doc"><small>{result.materialType?.toUpperCase()}</small><h2>{result.title}</h2>{p.proposito&&<p><b>Propósito:</b> {p.proposito}</p>}{p.instrucciones&&<p>{p.instrucciones}</p>}{(p.secciones||[]).map((s:any,n:number)=><section key={n}><h3>{s.titulo||"Sección "+(n+1)}</h3><p>{typeof s.contenido==="string"?s.contenido:JSON.stringify(s.contenido)}</p></section>)}{p.ilustraciones?.length>0&&<section><h3>Ilustraciones didácticas</h3><div className="generatedImages">{p.ilustraciones.map((img:any,n:number)=><figure key={n}><img src={img.image} alt={img.descripcion||"Ilustración educativa"}/><figcaption>{renderValue(img.descripcion)}</figcaption></figure>)}</div></section>}{p.cierre&&<><h3>Cierre</h3><p>{renderValue(p.cierre)}</p></>}<div className="materialActions"><button type="button" className="primary" onClick={()=>downloadSupportMaterial(result)}>↓ Descargar material en PDF</button><span>Incluye las ilustraciones IA generadas.</span></div></div>}<h3>Materiales recientes</h3><div className="folderGrid materialRecentGrid">{(data.materials||[]).slice(0,8).map((x:any)=><div className="folderCard materialRecentCard" key={x.id}><div><small>{x.materialType}</small><b>{x.title}</b><span>{x.course?.name||""}</span></div><button type="button" className="secondary compact" onClick={()=>downloadSupportMaterial(x)}>↓ PDF</button></div>)}</div></article>}

function IndividualHome({setTab}:{setTab:(x:string)=>void}){const[d,setD]=useState<any>(null);useEffect(()=>{fetch("/api/profile").then(r=>r.json()).then(setD).catch(()=>{})},[]);return <><div className="tpHero"><div><small>ESPACIO PERSONAL</small><h2>Hola, {d?.profile?.name||"Docente"}</h2><p>Crea, organiza y reutiliza tus recursos pedagógicos con IA.</p></div><div className="tpStat"><b>{d?.remainingAi??"—"}</b><span>generaciones IA disponibles</span></div></div><div className="kpis"><button className="kpi" onClick={()=>setTab("Planificaciones IA")}><b>Planificación IA</b><span>Crear planificación</span></button><button className="kpi" onClick={()=>setTab("Evaluaciones IA")}><b>Evaluación IA</b><span>Crear evaluación</span></button><button className="kpi" onClick={()=>setTab("Material de apoyo IA")}><b>Material de apoyo</b><span>Crear recurso educativo</span></button></div><article className="panel"><div className="panelHead"><div><small>MI ACTIVIDAD</small><h2>Resumen personal</h2></div></div><div className="kpis"><div className="kpi"><b>{d?.stats?.plannings||0}</b><span>Planificaciones</span></div><div className="kpi"><b>{d?.stats?.assessments||0}</b><span>Evaluaciones</span></div><div className="kpi"><b>{d?.stats?.materials||0}</b><span>Materiales</span></div><div className="kpi"><b>{d?.stats?.courses||0}</b><span>Cursos</span></div></div></article></>}
function IndividualProfile(){const[d,setD]=useState<any>(null);const[paying,setPaying]=useState(false);useEffect(()=>{fetch("/api/profile").then(r=>r.json()).then(setD).catch(()=>{})},[]);async function pay(){setPaying(true);try{const r=await fetch("/api/flow-checkout",{method:"POST"});const x=await r.json();if(!r.ok)throw new Error(x.error||"No fue posible iniciar el pago");window.location.href=x.checkoutUrl}catch(e:any){alert(e.message);setPaying(false)}}const p=d?.profile;const status:any={TRIAL:"Prueba activa",ACTIVE:"Plan activo",PAST_DUE:"Pago pendiente",CANCELED:"Cancelado"};return <article className="panel"><div className="tpHero"><div><small>MI CUENTA</small><h2>{p?.name||"Perfil docente"}</h2><p>{p?.email}</p></div><div className="tpStat"><b>{status[p?.subscriptionStatus]||"—"}</b><span>Docente Individual</span></div></div><div className="formGrid"><div className="callout"><b>Plan Individual</b><p><span>$21.000 neto + IVA $3.990</span><br/><b>Total: {p?.monthlyPriceClp?new Intl.NumberFormat("es-CL",{style:"currency",currency:"CLP",maximumFractionDigits:0}).format(p.monthlyPriceClp):"$24.990"} / mes · IVA incluido</b></p></div><div className="callout"><b>Uso de IA</b><p>{p?.monthlyAiUsed||0} / {p?.monthlyAiLimit||0} generaciones utilizadas</p></div><div className="callout"><b>Disponibles</b><p>{d?.remainingAi??0} generaciones IA</p></div><div className="callout"><b>{p?.subscriptionStatus==="TRIAL"?"Período de prueba":"Vigencia"}</b><p>{p?.subscriptionStatus==="TRIAL"?((d?.trialDays??0)+" días restantes"):(p?.subscriptionEndsAt?new Date(p.subscriptionEndsAt).toLocaleDateString("es-CL"):"—")}</p></div></div>{p?.subscriptionStatus==="TRIAL"&&<button className="primary" onClick={pay} disabled={paying}>{paying?"Conectando con Flow...":"Contratar Plan Individual · $24.990 IVA incluido"}</button>}</article>}
